using System.Net.Http.Json;
using System.Text.Json;
using System.Text.Json.Serialization;
using FutureClassroom.Core.Data;
using FutureClassroom.Core.Helpers;
using FutureClassroom.Job.Options;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Options;

namespace FutureClassroom.Job.Jobs.Implement;

/// <summary>
/// 同步台大課程資料與堂次資料（先同步課程，再依課程同步堂次）
/// </summary>
public class CourseLessonSync : ICourseLessonSync
{
    private readonly ILogger<CourseLessonSync> _logger;
    private readonly IDbContextFactory<AppDbContext> _dbFactory;
    private readonly IHttpClientFactory _httpClientFactory;
    private readonly string _courseSearchUrl;
    private readonly string _courseApiBase;
    private readonly string _coursePath;
    private readonly string _courseNameEnApiBase;

    // Q: Location 有可能有兩個，神經與行為模型建構有兩間教室
    private static readonly (string Teacher, string Name, string Location)[] Targets =
    [
        ("黃尹男", "應用力學2", "綜401"),
        ("陳怡秀", "氣候變遷對策：地球急轉彎", "綜401"),
        ("林以凡", "工程數學下", "綜401"),
        ("黃從仁", "神經與行為模型建構", "綜401"),
    ];

    public CourseLessonSync(ILogger<CourseLessonSync> logger, IDbContextFactory<AppDbContext> dbFactory, IHttpClientFactory httpClientFactory, IOptions<NtuCourseApiOptions> options)
    {
        _logger = logger;
        _dbFactory = dbFactory;
        _httpClientFactory = httpClientFactory;
        _courseSearchUrl = $"{options.Value.BaseUrl.TrimEnd('/')}/{options.Value.SearchPath.TrimStart('/')}";
        _courseApiBase = options.Value.BaseUrl.TrimEnd('/');
        _coursePath = options.Value.CoursePath.TrimStart('/');
        _courseNameEnApiBase = string.IsNullOrWhiteSpace(options.Value.DeptsBaseUrl) // 課程英文名稱要用新課程網 prod 才撈得到
            ? _courseApiBase
            : options.Value.DeptsBaseUrl.TrimEnd('/');
    }

    public async Task ExecuteAsync()
    {
        using var httpClient = _httpClientFactory.CreateClient("NTUCourseApi");
        await RunStepAsync(() => SyncCoursesAsync(httpClient), "課程", "所有指定老師的課程同步完成。");
        await RunStepAsync(() => SyncEnglishNamesAsync(httpClient), "英文課名", "所有課程英文名稱同步完成。");
        await RunStepAsync(() => SyncLessonsAsync(httpClient), "堂次", "所有課程堂次同步完成。");
    }

    private async Task<bool> RunStepAsync(Func<Task> step, string stepName, string successMessage)
    {
        _logger.LogInformation("開始同步{StepName}資料...", stepName);
        try
        {
            await step();
            _logger.LogInformation("{SuccessMessage}", successMessage);
            return true;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "同步{StepName}過程中發生未預期的錯誤", stepName);
            return false;
        }
    }

    /// <summary>
    /// Course sync
    /// </summary>
    /// <param name="httpClient"></param>
    /// <returns></returns>
    private async Task SyncCoursesAsync(HttpClient httpClient)
    {

        foreach (var (teacher, name, location) in Targets)
        {
            _logger.LogInformation("正在抓取 {Teacher} 的「{Name}」...", teacher, name);

            var requestBody = new
            {
                batchSize = 100,
                pageIndex = 0,
                sorting = "correlation",
                query = new
                {
                    keyword = name,
                    teacherKeyword = teacher,
                    locationKeyword = location,
                    excludedKeywords = Array.Empty<string>(),
                    time = new int[][] { [], [], [], [], [], [] },
                    isFullYear = (bool?)null,
                    timeStrictMatch = false,
                    enrollMethods = Array.Empty<string>(),
                    isEnglishTaught = false,
                    isDistanceLearning = false,
                    hasChanged = false,
                    isAdditionalCourse = false,
                    noPrerequisite = false,
                    departments = Array.Empty<string>(),
                    isCompulsory = (bool?)null
                }
            };

            var response = await httpClient.PostAsJsonAsync(_courseSearchUrl, requestBody);
            if (!response.IsSuccessStatusCode) continue;

            var result = await response.Content.ReadFromJsonAsync<NtuApiResult>();
            if (result?.Courses == null || result.Courses.Count == 0)
            {
                _logger.LogWarning("API 未搜到課程: {Teacher} {Name}", teacher, name);
                continue;
            }

            await using var db = await _dbFactory.CreateDbContextAsync();

            foreach (var item in result.Courses)
            {
                if (!item.Name.Equals(name, StringComparison.OrdinalIgnoreCase))
                    continue;

                var semester = item.Semester.Replace("-", "");
                var courseKey = $"{semester}_{item.Code}_{item.Class ?? ""}";
                var classroom = item.Schedules?.FirstOrDefault()?.Classroom;

                var course = await db.Courses.FirstOrDefaultAsync(c => c.CourseKey == courseKey);
                if (course == null)
                {
                    course = new Course { CourseKey = courseKey, CreatedAt = DateTime.UtcNow };
                    db.Courses.Add(course);
                }

                course.CourseId = item.Code;
                course.Serial = item.Serial;
                course.Name = item.Name;
                var nameEn = await FetchEnglishNameAsync(httpClient, semester, item.Serial);
                if (nameEn != null)
                    course.NameEn = nameEn;
                course.Semester = semester;
                course.Section = item.Class;
                course.TeacherId = item.Teacher?.Id ?? "Unknown";
                course.TeacherName = item.Teacher?.Name ?? "Unknown";
                course.TotalStudentQuota = item.TotalStudentQuota;
                course.ClassroomName = classroom?.Name;
                course.ClassroomLocation = classroom?.Location;
                course.BuildingName = classroom?.BuildingName;
                course.BuildingId = classroom?.BuildingId;
                course.SchedulesJson = JsonSerializer.Serialize(
                    (item.Schedules ?? []).Select(s =>
                    {
                        var sorted = s.Intervals.Order().ToList();
                        return new
                        {
                            weekday = s.Weekday.ToString(),
                            start_session = sorted.FirstOrDefault() ?? "0",
                            end_session = sorted.LastOrDefault() ?? "0"
                        };
                    })
                );
                course.UpdatedAt = DateTime.UtcNow;
            }

            await db.SaveChangesAsync();
        }
    }

    /// <summary>
    /// Fill NameEn for every stored course via https://course.ntu.edu.tw/api/v3/course?semester={semester}&serial={serial}&lang=en_US.
    /// </summary>
    private async Task SyncEnglishNamesAsync(HttpClient httpClient)
    {
        await using var db = await _dbFactory.CreateDbContextAsync();
        var courses = await db.Courses
            .Where(c => !string.IsNullOrEmpty(c.Serial))
            .ToListAsync();

        foreach (var course in courses)
        {
            _logger.LogInformation("正在抓取 {CourseKey} 的英文名稱 (serial={Serial})...", course.CourseKey, course.Serial);
            var nameEn = await FetchEnglishNameAsync(httpClient, course.Semester, course.Serial);
            if (nameEn is null)
                continue;

            course.NameEn = nameEn;
            course.UpdatedAt = DateTime.UtcNow;
        }

        await db.SaveChangesAsync();
    }

    /// <summary>
    /// Lesson sync
    /// </summary>
    /// <param name="http"></param>
    /// <returns></returns>
    private async Task SyncLessonsAsync(HttpClient http)
    {
        await using var db = await _dbFactory.CreateDbContextAsync();

        var courses = await db.Courses
            .Select(c => new { c.CourseKey, c.Semester, c.Serial })
            .ToListAsync();

        foreach (var course in courses)
        {
            if (string.IsNullOrEmpty(course.Serial)) continue;

            var semesterApi = ToApiSemester(course.Semester);
            var url = $"{_courseApiBase}/{_coursePath}?semester={semesterApi}&serial={course.Serial}&syllabus=true";

            _logger.LogInformation("正在同步 {CourseKey} 的堂次 (serial={Serial})...", course.CourseKey, course.Serial);

            NtuCourseResponse? response;
            try
            {
                response = await http.GetFromJsonAsync<NtuCourseResponse>(url);
            }
            catch (Exception ex)
            {
                _logger.LogWarning(ex, "無法取得 {CourseKey} 的課程資料", course.CourseKey);
                continue;
            }

            await ClearLessonsAsync(db, course.CourseKey);
            await InsertLessonsAsync(db, course.CourseKey, semesterApi, response?.Syllabus?.Progress);
        }
    }

    private async Task<string?> FetchEnglishNameAsync(HttpClient httpClient, string semester, string serial)
    {
        var semesterApi = ToApiSemester(semester);
        var url = $"{_courseNameEnApiBase}/{_coursePath}?semester={semesterApi}&serial={Uri.EscapeDataString(serial)}&lang=en_US";
        try
        {
            var response = await httpClient.GetFromJsonAsync<NtuCourseResponse>(url);
            return string.IsNullOrWhiteSpace(response?.Name) ? null : response.Name;
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "無法取得 serial={Serial} 的英文課程名稱", serial);
            return null;
        }
    }

    // "1142" → "114-2"
    private static string ToApiSemester(string semester) =>
        semester.Length == 4 ? semester[..3] + "-" + semester[3..] : semester;

    private async Task ClearLessonsAsync(AppDbContext db, string courseKey)
    {
        var toDelete = await db.Lessons.Where(l => l.CourseKey == courseKey).ToListAsync();
        if (toDelete.Count > 0)
        {
            db.Lessons.RemoveRange(toDelete);
            await db.SaveChangesAsync();
        }
    }

    private async Task InsertLessonsAsync(AppDbContext db, string courseKey, string semesterApi, List<NtuProgressItem>? progress)
    {
        if (progress is null || progress.Count <= 0)
            return;

        var rocYear = int.Parse(semesterApi[..3]);
        var semPart = semesterApi[^1] - '0';
        var gregorianYear = rocYear + 1911;

        foreach (var item in progress)
        {
            if (!int.TryParse(item.Week, out var weekNum)) continue;
            var dates = ParseAllDates(item.Date, semPart, gregorianYear).ToList();
            if (dates.Count == 0) continue;

            var topic = string.IsNullOrWhiteSpace(item.Content) ? "" : item.Content;

            for (var i = 0; i < dates.Count; i++)
            {
                var lessonId = CourseHelper.BuildLessonId(courseKey, weekNum, dates[i]);
                var lessonDate = DateTime.SpecifyKind(dates[i], DateTimeKind.Utc);

                db.Lessons.Add(new Lesson
                {
                    LessonId = lessonId,
                    CourseKey = courseKey,
                    WeekNumber = weekNum,
                    LessonDate = lessonDate,
                    Topic = topic
                });
            }
        }

        await db.SaveChangesAsync();
    }

    // Parses all dates from strings like "02/23, 02/25".
    // Year inferred from semester: spring (2) → gregorianYear; fall (1) → month >= 8 means previous Gregorian year.
    private static IEnumerable<DateTime> ParseAllDates(string? dateStr, int semPart, int gregorianYear)
    {
        if (string.IsNullOrWhiteSpace(dateStr)) yield break;
        foreach (var part in dateStr.Split(','))
        {
            var segments = part.Trim().Split('/');
            if (segments.Length != 2) continue;
            if (!int.TryParse(segments[0], out var month) || !int.TryParse(segments[1], out var day)) continue;
            var year = semPart == 2 ? gregorianYear : month >= 8 ? gregorianYear - 1 : gregorianYear;
            DateTime date;
            try { date = new DateTime(year, month, day); }
            catch { continue; }
            yield return date;
        }
    }
}

