using FutureClassroom.Api.Services;
using FutureClassroom.Core.Helpers;

namespace FutureClassroom.Api.Endpoints;

public static class CourseEndpoints
{
    public static void MapNTUCourseApi(this WebApplication app)
    {
        var isDev = app.Environment.IsDevelopment();
        var group = app.MapGroup("/courses");

        if (!isDev)
        {
            group.RequireAuthorization();
        }

        // GET /courses
        // Now
        // 所有課程

        // 未來可能:
        // 只能看到自己授課的課程

        // 排程: 自動從 NTU Course API 抓取資料並更新資料庫

        /// <summary>
        /// 所有課程
        /// </summary>
        /// <param name="semester"></param>
        group.MapGet("/", async (HttpContext context, CourseService courseService, string? semester) =>
        {

            if (semester is not null && (semester.Length != 4 || !semester.All(char.IsDigit)))
                return ApiErrors.InvalidParameter();



            try
            {

                // // phase 1: 先不做權限控管，直接回傳所有未來教室課程資料 //////////////////////////
                // // TODO: 之後要改成只能看到自己授課的課程

                // var teacherName = "林以凡"; 
                // // 宜桓、尹男林以凡、謝宜桓、黃尹男

                // var location = "綜401";
                ///////////////////////////////////////////////////////////////////////
                var response = await courseService.GetCoursesAsync(semester: semester);

                if (response.Semesters.Count == 0)
                    return ApiErrors.NotFound("no_courses_found", "No courses found for the specified semester.");

                return Results.Ok(response);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"[CourseEndpoints] Exception: {ex}");
                return ApiErrors.InternalError();
            }
        }).WithSummary("所有課程");

        /// <summary>
        /// 課程週覽
        /// </summary>
        /// <param name="courseKey"></param>
        group.MapGet("/{courseKey}/lessons", async (
            string courseKey,
            CourseService courseService
        ) =>
        {
            courseKey = CourseHelper.DecodePathValue(courseKey);

            if (string.IsNullOrWhiteSpace(courseKey) || courseKey.Split('_').Length < 2)
                return ApiErrors.InvalidParameter();

            try
            {
                var result = await courseService.GetCourseLessonsAsync(courseKey);
                return Results.Ok(result);
            }
            catch (KeyNotFoundException)
            {
                return ApiErrors.NotFound("no_courses_found", "No courses found for the specified course key.");
            }
        }).WithSummary("課程週覽");
    }
}

