using Microsoft.Extensions.Options;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authentication.Cookies;
using Sustainsys.Saml2.AspNetCore2;
using System.Security.Claims;
using FutureClassroom.Api.Models;
using FutureClassroom.Api.Options;
using FutureClassroom.Api.Services;

namespace FutureClassroom.Api.Endpoints;

public static class SsoEndpoints {
    private const string AuthScheme = CookieAuthenticationDefaults.AuthenticationScheme;

    public static void MapSsoApi(this IEndpointRouteBuilder app, bool enableTestCallback = false) {
        var group = app.MapGroup("/auth");

        // NTU SSO
        group.MapGet("/login", async (HttpContext context, IOptions<FutureClassroomOptions> fcOpt) => {
            try {
                var callbackUrl = $"{fcOpt.Value.BaseUrl}auth/callback";

                var props = new AuthenticationProperties { RedirectUri = callbackUrl };
                await context.ChallengeAsync(Saml2Defaults.Scheme, props);
            }
            catch {
                Results.Problem("Failed to initialize login flow.", statusCode: 500);
            }
        });

        group.MapGet("/callback", async Task<IResult> (HttpContext context, IOptions<FutureClassroomOptions> fcOpt) => {
            var result = await context.AuthenticateAsync(AuthScheme);
            if (!result.Succeeded)
                return ApiErrors.Unauthorized("SSO authentication failed.");

            var claimsIdentity = result.Principal?.Identity as System.Security.Claims.ClaimsIdentity;
            var ntuAccountName = claimsIdentity?.FindFirst("http://www.ntu.edu.tw/AccountName")?.Value;
            var ntuChineseName = claimsIdentity?.FindFirst("http://www.ntu.edu.tw/ChineseName")?.Value;
            var ntuSeq = claimsIdentity?.FindFirst("http://www.ntu.edu.tw/SEQ")?.Value;
            var ntuTypeCode = claimsIdentity?.FindFirst("http://www.ntu.edu.tw/AccountTypeCode")?.Value;
            var ntuMajor = claimsIdentity?.FindFirst("http://www.ntu.edu.tw/UNITB")?.Value;

            await SignInUserAsync(context, ntuAccountName ?? "", ntuChineseName ?? "台大使用者", ntuSeq ?? "", ntuTypeCode ?? "", ntuMajor ?? "", AuthScheme);

            return Results.Redirect($"{fcOpt.Value.FrontendUrl}");
        });

        // 在開發環境模擬正式的 POST 回傳
        if (enableTestCallback) {
            group.MapPost("/test-callback", async (HttpContext context, IOptions<FutureClassroomOptions> fcOpt) => {

                // 模擬從台大拿到的資料
                string mockAccount = "r14725046";
                string mockName = "陳書雁";
                string mockSeq = "r14725046";
                string mockTypeCode = "u";
                string mockMajor = "資訊管理學系";


                await SignInUserAsync(context, mockAccount, mockName, mockSeq, mockTypeCode, mockMajor, AuthScheme);

                return Results.Ok(new {
                    status = "Success",
                    message = "Cookie 已發放，請造訪 /auth/me 確認",
                });
            });
        }

        group.MapGet("/logout", async Task<IResult> (
            HttpContext context,
            IWebHostEnvironment env,
            IOptions<NtuSsoOptions> ssoOpt,
            IOptions<FutureClassroomOptions> fcOpt) => {

            await context.SignOutAsync(AuthScheme);

            var returnUrl = $"{fcOpt.Value.FrontendUrl}login";

            if (env.IsDevelopment())
                return Results.Redirect(returnUrl); // 在本機開發時導回本地端登入頁

            var logoutUrl = $"{ssoOpt.Value.BaseUrl}logout?url={Uri.EscapeDataString(returnUrl)}";

            return Results.Redirect(logoutUrl);
        });

        group.MapGet("/me", async (HttpContext context, DepartmentService departments) => {

            if (context.User.Identity?.IsAuthenticated != true) {
                return ApiErrors.Unauthorized();
            }
            var id = context.User.FindFirst("StudentId")?.Value;
            var name = context.User.FindFirst(ClaimTypes.Name)?.Value;
            var department = context.User.FindFirst("Major")?.Value;
            var role = context.User.FindFirst("UserType")?.Value;

            var resolved = await departments.FindByMajorAsync(department);

            return Results.Ok(new UserResponse(
                User: new UserInfo(
                    Id: id ?? "",
                    Name: name ?? "",
                    Department: department,
                    DepartmentZh: resolved?.NameZh ?? department,
                    DepartmentEn: resolved?.NameEn ?? department,
                    Role: role ?? ""
                )
            ));
        }); 

    }

    private static string MapRole(string accountTypeCode) => accountTypeCode switch
    {
        "u" or "g" => "student",
        "f" => "teacher",
        _ => "consultant"
    };

    private static async Task SignInUserAsync(HttpContext context, string account, string name, string seq, string typeCode, string major, string authScheme)
    {
        var claims = new List<Claim>
        {
            new Claim(ClaimTypes.NameIdentifier, account),
            new Claim(ClaimTypes.Name, name),
            new Claim("StudentId", account),
            new Claim("AccountSeq", seq),
            new Claim("UserType", MapRole(typeCode)),
            new Claim("Major", major)
        };

        var identity = new ClaimsIdentity(claims, authScheme);
        await context.SignInAsync(authScheme, new ClaimsPrincipal(identity));
    }
}

