using Microsoft.AspNetCore.DataProtection.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

namespace FutureClassroom.Core.Data;

public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options), IDataProtectionKeyContext {
    public DbSet<Course> Courses => Set<Course>();
    public DbSet<Lesson> Lessons => Set<Lesson>();
    public DbSet<Department> Departments => Set<Department>();
    public DbSet<AiResult> AiResults => Set<AiResult>();
    public DbSet<AiWindow> AiWindows => Set<AiWindow>();
    public DbSet<AiWindowSeat> AiWindowSeats => Set<AiWindowSeat>();
    public DbSet<DataProtectionKey> DataProtectionKeys => Set<DataProtectionKey>();

    protected override void OnModelCreating(ModelBuilder modelBuilder) {
        modelBuilder.Entity<Course>(e => {
            e.HasKey(c => c.Id);
            e.HasIndex(c => c.CourseKey).IsUnique();
            e.HasIndex(c => c.Serial);
            e.Property(c => c.CourseKey).HasMaxLength(64);
            e.Property(c => c.CourseId).HasMaxLength(32);
            e.Property(c => c.Serial).HasMaxLength(16);
            e.Property(c => c.Semester).HasMaxLength(8);
            e.Property(c => c.Section).HasMaxLength(8);
            e.Property(c => c.TeacherId).HasMaxLength(32);
            e.Property(c => c.ClassroomName).HasMaxLength(32);
            e.Property(c => c.BuildingId).HasMaxLength(16);
        });

        modelBuilder.Entity<Lesson>(e => {
            e.HasKey(l => l.Id);
            e.HasIndex(l => l.LessonId).IsUnique();
            e.HasIndex(l => l.CourseKey);
            e.Property(l => l.LessonId).HasMaxLength(64);
            e.Property(l => l.CourseKey).HasMaxLength(64);
            e.Property(l => l.Status).HasMaxLength(32);
            e.HasOne(l => l.Course)
                .WithMany(c => c.Lessons)
                .HasForeignKey(l => l.CourseKey)
                .HasPrincipalKey(c => c.CourseKey);
        });

        modelBuilder.Entity<Department>(e => {
            e.HasKey(d => d.Id);
            e.HasIndex(d => d.DeptCode).IsUnique();
            e.HasIndex(d => d.NameZh);
            e.HasIndex(d => d.ShortNameZh);
            e.Property(d => d.DeptCode).HasMaxLength(8);
            e.Property(d => d.NameZh).HasMaxLength(512);
            e.Property(d => d.NameEn).HasMaxLength(512);
            e.Property(d => d.ShortNameZh).HasMaxLength(128);
            e.Property(d => d.ShortNameEn).HasMaxLength(128);
        });

        modelBuilder.Entity<AiResult>(e => {
            e.HasKey(r => r.Id);
            e.HasIndex(r => r.LessonId).IsUnique();
            e.HasIndex(r => r.CourseKey);
            e.Property(r => r.LessonId).HasMaxLength(64);
            e.Property(r => r.CourseKey).HasMaxLength(64);
            e.Property(r => r.Semester).HasMaxLength(8);
            e.Property(r => r.CourseId).HasMaxLength(32);
            e.Property(r => r.ClassSection).HasMaxLength(8);
            e.Property(r => r.Week).HasMaxLength(4);
            e.Property(r => r.VideoPath).HasMaxLength(500);
        });

        modelBuilder.Entity<AiWindow>(e => {
            e.HasKey(w => new { w.LessonId, w.WindowIndex });
            e.HasIndex(w => w.LessonId);
            e.Property(w => w.LessonId).HasMaxLength(64);
        });

        modelBuilder.Entity<AiWindowSeat>(e => {
            e.HasKey(s => new { s.LessonId, s.WindowIndex, s.SeatKey, s.EngagementLevel });
            e.HasIndex(s => s.LessonId);
            e.HasIndex(s => new { s.LessonId, s.WindowIndex });
            e.Property(s => s.LessonId).HasMaxLength(64);
            e.Property(s => s.SeatKey).HasMaxLength(16);
            e.Property(s => s.GroupKey).HasMaxLength(8);
            e.Property(s => s.EngagementLevel).HasMaxLength(8);
            e.HasOne<AiWindow>()
                .WithMany()
                .HasForeignKey(s => new { s.LessonId, s.WindowIndex })
                .OnDelete(DeleteBehavior.Cascade);
        });
    }
}

