namespace FutureClassroom.Core.Helpers;

public static class CourseHelper
{
    /// <summary>
    /// 取得MinIO影片路徑，格式為：recordings/{semester}/{courseId}/{section}/{generatedAt}_{semester}_{courseId}_{section}_{classroomCode}_projector.mp4
    /// </summary>
    /// <param name="semester"></param>
    /// <param name="courseId"></param>
    /// <param name="section"></param>
    /// <param name="generatedAt"></param>
    /// <param name="classroomCode"></param>
    /// <returns></returns>
    public static string BuildVideoKey(string semester, string courseId, string? section, DateTime generatedAt, string classroomCode = "M10-401")
    {
        var s = FormatSemester(semester);
        var c = FormatCourseId(courseId);
        var sec = FormatSection(section);
        return $"recordings/{s}/{c}/{sec}/{generatedAt:yyyy-MM-dd-HH-mm-ss}_{s}_{c}_{sec}_{classroomCode}_projector1.mp4";
    }

    /// <summary>
    /// 取得LessonId
    /// </summary>
    /// <param name="courseKey"></param>
    /// <param name="weekNum"></param>
    /// <param name="date"></param>
    /// <returns></returns>
    public static string BuildLessonId(string courseKey, int weekNum, DateTime date)
    {
        return $"{courseKey}_{weekNum}_{date:MMdd}";
    }

    /// <summary>
    /// 解碼 URL path 參數。Kestrel 與反向代理對 %20 的處理不一致，
    /// DB 存的是空白（例如 502 20002），所以這裡統一還原成空白。
    /// </summary>
    public static string DecodePathValue(string value)
    {
        if (string.IsNullOrEmpty(value))
            return value;

        var current = value;
        // 最多解兩次：有些代理會把空白編成 %20，再被編成 %2520。
        for (var i = 0; i < 2; i++)
        {
            if (current.IndexOf('%') < 0)
                break;

            try
            {
                var decoded = Uri.UnescapeDataString(current);
                if (decoded == current)
                    break;
                current = decoded;
            }
            catch (UriFormatException)
            {
                break;
            }
        }

        return current;
    }

    private static string FormatSemester(string semester) =>
        semester.Length >= 2 ? semester[..^1] + "-" + semester[^1] : semester;

    private static string FormatCourseId(string courseId)
    {
        return $"{courseId[..3]}-{courseId[4..]}";
    }

    private static string FormatSection(string? section)
    {
        if (string.IsNullOrEmpty(section)) return "0";
        return int.TryParse(section, out var n) ? n.ToString("D2") : section;
    }
}

