using System.Net.Http.Json;
using System.Text.Json.Serialization;
using FutureClassroom.Core.Data;
using FutureClassroom.Job.Options;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Options;

namespace FutureClassroom.Job.Jobs.Implement;

/// <summary>
/// 從台大課程網抓取系所中英文名稱並寫入 Departments。
/// </summary>
public class DepartmentSync : IDepartmentSync
{
    private const int MaxDeptCodeLength = 8;
    private const int MaxNameLength = 512;
    private const int MaxShortNameLength = 128;

    private readonly ILogger<DepartmentSync> _logger;
    private readonly IDbContextFactory<AppDbContext> _dbFactory;
    private readonly IHttpClientFactory _httpClientFactory;
    private readonly string _deptsUrl;

    public DepartmentSync(
        ILogger<DepartmentSync> logger,
        IDbContextFactory<AppDbContext> dbFactory,
        IHttpClientFactory httpClientFactory,
        IOptions<NtuCourseApiOptions> options)
    {
        _logger = logger;
        _dbFactory = dbFactory;
        _httpClientFactory = httpClientFactory;

        var opts = options.Value;
        var baseUrl = string.IsNullOrWhiteSpace(opts.DeptsBaseUrl) ? opts.BaseUrl : opts.DeptsBaseUrl;
        var path = string.IsNullOrWhiteSpace(opts.DeptsPath) ? "api/v1/depts" : opts.DeptsPath;
        _deptsUrl = $"{baseUrl.TrimEnd('/')}/{path.TrimStart('/')}";
    }

    public async Task ExecuteAsync()
    {
        _logger.LogInformation("開始同步台大系所中英文名稱...");
        try
        {
            using var httpClient = _httpClientFactory.CreateClient("NTUCourseApi");
            var zhItems = await FetchDepartmentsAsync(httpClient, "zh_TW");
            var enItems = await FetchDepartmentsAsync(httpClient, "en_US");

            if (zhItems.Count == 0 && enItems.Count == 0)
            {
                _logger.LogWarning("台大系所 API 未回傳任何資料，略過寫入。");
                return;
            }

            var merged = MergeById(zhItems, enItems);
            await UpsertAsync(merged);
            _logger.LogInformation("台大系所同步完成，共 {Count} 筆。", merged.Count);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "同步台大系所過程中發生未預期的錯誤");
            throw;
        }
    }

    private async Task<List<NtuDeptItem>> FetchDepartmentsAsync(HttpClient httpClient, string lang)
    {
        var url = $"{_deptsUrl}?lang={Uri.EscapeDataString(lang)}";
        _logger.LogInformation("正在抓取系所列表: {Url}", url);

        var response = await httpClient.GetAsync(url);
        if (!response.IsSuccessStatusCode)
        {
            _logger.LogWarning("系所 API 失敗 lang={Lang} status={Status}", lang, (int)response.StatusCode);
            return [];
        }

        var result = await response.Content.ReadFromJsonAsync<NtuDeptsResponse>();
        var items = result?.Departments ?? [];
        _logger.LogInformation("系所 API lang={Lang} 回傳 {Count} 筆。", lang, items.Count);
        return items;
    }

    private static Dictionary<string, (NtuDeptItem? Zh, NtuDeptItem? En)> MergeById(
        List<NtuDeptItem> zhItems,
        List<NtuDeptItem> enItems)
    {
        var merged = new Dictionary<string, (NtuDeptItem? Zh, NtuDeptItem? En)>(StringComparer.Ordinal);

        foreach (var item in zhItems)
        {
            var id = item.Id?.Trim();
            if (string.IsNullOrEmpty(id)) continue;
            merged[id] = (item, null);
        }

        foreach (var item in enItems)
        {
            var id = item.Id?.Trim();
            if (string.IsNullOrEmpty(id)) continue;
            if (merged.TryGetValue(id, out var existing))
                merged[id] = (existing.Zh, item);
            else
                merged[id] = (null, item);
        }

        return merged;
    }

    private async Task UpsertAsync(Dictionary<string, (NtuDeptItem? Zh, NtuDeptItem? En)> merged)
    {
        await using var db = await _dbFactory.CreateDbContextAsync();
        var existing = await db.Departments.ToDictionaryAsync(d => d.DeptCode, StringComparer.Ordinal);
        var now = DateTime.UtcNow;

        foreach (var (id, pair) in merged)
        {
            var deptCode = Truncate(id, MaxDeptCodeLength);
            var nameZh = Truncate(FirstNonEmpty(pair.Zh?.Name, pair.En?.Name), MaxNameLength);
            var nameEn = Truncate(FirstNonEmpty(pair.En?.Name, pair.Zh?.Name), MaxNameLength);
            if (string.IsNullOrEmpty(nameZh) && string.IsNullOrEmpty(nameEn))
                continue;

            var shortZh = TruncateNullable(Normalize(pair.Zh?.ShortName), MaxShortNameLength);
            var shortEn = TruncateNullable(Normalize(pair.En?.ShortName), MaxShortNameLength);

            if (!existing.TryGetValue(deptCode, out var row))
            {
                row = new Department
                {
                    DeptCode = deptCode,
                    CreatedAt = now,
                };
                db.Departments.Add(row);
                existing[deptCode] = row;
            }

            row.NameZh = nameZh;
            row.NameEn = nameEn;
            row.ShortNameZh = shortZh;
            row.ShortNameEn = shortEn;
            row.UpdatedAt = now;
        }

        await db.SaveChangesAsync();
    }

    private static string FirstNonEmpty(string? primary, string? fallback)
    {
        if (!string.IsNullOrWhiteSpace(primary)) return primary.Trim();
        if (!string.IsNullOrWhiteSpace(fallback)) return fallback.Trim();
        return string.Empty;
    }

    private static string? Normalize(string? value) =>
        string.IsNullOrWhiteSpace(value) ? null : value.Trim();

    private static string Truncate(string value, int max) =>
        value.Length <= max ? value : value[..max];

    private static string? TruncateNullable(string? value, int max) =>
        value is null ? null : Truncate(value, max);

    private class NtuDeptsResponse
    {
        [JsonPropertyName("departments")]
        public List<NtuDeptItem> Departments { get; set; } = [];
    }

    private class NtuDeptItem
    {
        [JsonPropertyName("id")]
        public string? Id { get; set; }

        [JsonPropertyName("name")]
        public string? Name { get; set; }

        [JsonPropertyName("shortName")]
        public string? ShortName { get; set; }
    }
}

