using System.Security.Cryptography;

namespace FutureClassroom.Core.Helpers;

// 用共用金鑰（Base64，32 bytes）對新課程網 token 做 AES-256-GCM 加解密。
// Api（加密）與 Job（解密）是兩個獨立部署的行程，改用共用金鑰而不是 ASP.NET Core
// DataProtection 金鑰環，避免 Worker 服務要額外掛 ASP.NET Core shared framework 才能互通。
public static class TokenCipher
{
    private const int NonceSize = 12;
    private const int TagSize = 16;

    public static string Encrypt(string plaintext, string base64Key)
    {
        var key = Convert.FromBase64String(base64Key);
        var nonce = RandomNumberGenerator.GetBytes(NonceSize);
        var plainBytes = System.Text.Encoding.UTF8.GetBytes(plaintext);
        var cipherBytes = new byte[plainBytes.Length];
        var tag = new byte[TagSize];

        using (var aes = new AesGcm(key, TagSize))
        {
            aes.Encrypt(nonce, plainBytes, cipherBytes, tag);
        }

        var combined = new byte[NonceSize + cipherBytes.Length + TagSize];
        Buffer.BlockCopy(nonce, 0, combined, 0, NonceSize);
        Buffer.BlockCopy(cipherBytes, 0, combined, NonceSize, cipherBytes.Length);
        Buffer.BlockCopy(tag, 0, combined, NonceSize + cipherBytes.Length, TagSize);
        return Convert.ToBase64String(combined);
    }

    public static string Decrypt(string encrypted, string base64Key)
    {
        var key = Convert.FromBase64String(base64Key);
        var combined = Convert.FromBase64String(encrypted);

        var nonce = combined[..NonceSize];
        var tag = combined[^TagSize..];
        var cipherBytes = combined[NonceSize..^TagSize];
        var plainBytes = new byte[cipherBytes.Length];

        using (var aes = new AesGcm(key, TagSize))
        {
            aes.Decrypt(nonce, cipherBytes, tag, plainBytes);
        }

        return System.Text.Encoding.UTF8.GetString(plainBytes);
    }
}

