namespace FutureClassroom.Api.Endpoints;

public record ErrorDetail(string Code, string Message);
public record ErrorResponse(List<ErrorDetail> Errors);

public static class ApiErrors {
    public static IResult Error(string code, string message, int status) =>
        Results.Json(new ErrorResponse([new(code, message)]), statusCode: status);

    public static IResult Unauthorized(string message = "Session expired, please login again") =>
        Error("unauthorized", message, 401);

    public static IResult InvalidParameter(string message = "The parameter format is invalid.") =>
        Error("invalid_parameter", message, 400);

    public static IResult NotFound(string code, string message) =>
        Error(code, message, 404);

    public static IResult InternalError(string message = "An unexpected error occurred on the server. Please try again later.") =>
        Error("internal_error", message, 500);
}

