using System.ComponentModel;

namespace FutureClassroom.Core.Jobs;

// 放在 Core 而不是 FutureClassroom.Job，因為 Api 需要用這個介面型別透過 Hangfire enqueue，
// 但 Api 不應該直接參考整個 FutureClassroom.Job 專案。
public interface IEnrollmentSync
{
    /// <summary>
    /// 同步學生的最終選課結果（新課程網 Final phase）
