using System.Security.Claims;
using FutureClassroom.Api.Options;
using FutureClassroom.Core.Data;
using FutureClassroom.Core.Helpers;
using FutureClassroom.Core.Jobs;
using Hangfire;
using Microsoft.Extensions.Options;

namespace FutureClassroom.Api.Endpoints;

public record CourseNetworkTokenRequest(string Token);

public static class CourseNetworkEndpoints {
    private static readonly TimeSpan TokenTtl = TimeSpan.FromMinutes(10);

    public static void MapCourseNetworkApi(this WebApplication app) {
        var group = app.MapGroup("/auth").RequireAuthorization();

        // 前端走完新課程網 OAuth 拿到該學生的 bearer token 後，POST 給後端，
        // 後端加密短效存放並觸發背景 job 去撈該生的最終選課結果。
        group.MapPost("/course-network-token", async (
            HttpContext context,
            CourseNetworkTokenRequest request,
            AppDbContext db,
            IBackgroundJobClient backgroundJobClient,
            IOptions<CourseSelectionOptions> courseSelectionOptions,
            IConfiguration configuration
        ) => {
            var studentId = context.User.FindFirst("StudentId")?.Value;
            if (string.IsNullOrEmpty(studentId))
                return ApiErrors.Unauthorized();

            if (string.IsNullOrWhiteSpace(request.Token))
                return ApiErrors.InvalidParameter("Token is required.");

            var key = configuration["CourseNetworkTokenKey"];
            if (string.IsNullOrEmpty(key))
                return ApiErrors.InternalError("CourseNetworkTokenKey is not configured.");

            var semester = courseSelectionOptions.Value.CurrentSemester;
            if (string.IsNullOrEmpty(semester))
                return ApiErrors.InternalError("CurrentSemester is not configured.");

            var pending = new PendingCourseNetworkToken {
                StudentId = studentId,
                EncryptedToken = TokenCipher.Encrypt(request.Token, key),
                ExpiresAt = DateTime.UtcNow.Add(TokenTtl)
            };
            db.PendingCourseNetworkTokens.Add(pending);
            await db.SaveChangesAsync();

            backgroundJobClient.Enqueue<IEnrollmentSync>(job => job.ExecuteAsync(studentId, semester, pending.Id));

            return Results.Accepted();
        });
    }
}

