﻿using Amazon.S3;
using FutureClassroom.Api.Options;
using FutureClassroom.Api.Endpoints;
using FutureClassroom.Api.Services;
using FutureClassroom.Core.Data;
using FutureClassroom.Api.Auth;
using Hangfire;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.EntityFrameworkCore;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.HttpOverrides;
using Sustainsys.Saml2;
using Sustainsys.Saml2.AspNetCore2;
using Sustainsys.Saml2.Metadata;
using System.Security.Cryptography.X509Certificates;
using Sustainsys.Saml2.Saml2P;
using FutureClassroom.Core.Factory;

var builder = WebApplication.CreateBuilder(args);

builder.WebHost.ConfigureKestrel(o => o.Limits.MaxRequestBodySize = null);
builder.Services.Configure<Microsoft.AspNetCore.Http.Features.FormOptions>(o => {
    o.MultipartBodyLengthLimit = long.MaxValue;
});


builder.Services.Configure<NtuSsoOptions>(builder.Configuration.GetSection("NtuSso"));
builder.Services.Configure<FutureClassroomOptions>(builder.Configuration.GetSection("FutureClassroomApi"));
builder.Services.Configure<CourseSelectionOptions>(builder.Configuration.GetSection("CourseSelection"));

var connectionString = builder.Configuration.GetConnectionString("Default")
    ?? throw new InvalidOperationException("Connection string 'Default' not found.");

builder.Services.AddDbContext<AppDbContext>(opt =>
    opt.UseNpgsql(connectionString,
        npgsql => npgsql.MigrationsAssembly(typeof(Program).Assembly.FullName)));

// Client-only：只把 job enqueue 進 FutureClassroom.Job 共用的同一個 Postgres storage，不跑 worker。
builder.Services.AddHangfire(config => config
    .UsePostgreSqlStorage(o => o.UseNpgsqlConnection(connectionString)));


builder.Services.AddKeyedSingleton<IAmazonS3>("s3", (_, _) =>
{
    var s3Config = builder.Configuration.GetSection("S3");
    return new AmazonS3Client(s3Config["AccessKey"] ?? "", s3Config["SecretKey"] ?? "", new AmazonS3Config
    {
        ServiceURL = s3Config["ServiceUrl"],
        ForcePathStyle = true,
        AuthenticationRegion = "us-east-1",
        HttpClientFactory = new BypassSslHttpClientFactory()
    });
});

builder.Services.AddScoped<CourseService>();
builder.Services.AddScoped<LessonService>();
builder.Services.AddScoped<DepartmentService>();
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen();
builder.Services.ConfigureHttpJsonOptions(o =>
    o.SerializerOptions.PropertyNamingPolicy = System.Text.Json.JsonNamingPolicy.SnakeCaseLower);


var ntuSsoOptions = builder.Configuration.GetSection("NtuSso").Get<NtuSsoOptions>()!;
var fcOptions = builder.Configuration.GetSection("FutureClassroomApi").Get<FutureClassroomOptions>()!;
var baseUrlPath = builder.Configuration.GetValue<string>("BaseUrlPath")!;

var baseUrl = fcOptions.BaseUrl;
var ssoUrl = ntuSsoOptions.BaseUrl;

builder.Services.AddDataProtection()
    .PersistKeysToDbContext<AppDbContext>()
    .SetApplicationName(baseUrlPath);

builder.Services.AddAuthentication(options => {
    options.DefaultScheme = CookieAuthenticationDefaults.AuthenticationScheme;
    options.DefaultChallengeScheme = Saml2Defaults.Scheme;
})
.AddCookie(options => {
    options.Cookie.Name = $"_{baseUrlPath}";
    options.ExpireTimeSpan = TimeSpan.FromHours(8);
    options.LoginPath = "/auth/login";
    options.Events.OnRedirectToLogin = ctx => {
        ctx.Response.StatusCode = 401;
        return Task.CompletedTask;
    };
    options.Events.OnRedirectToAccessDenied = ctx => {
        ctx.Response.StatusCode = 403;
        return Task.CompletedTask;
    };
})
.AddSaml2(options => {
    var env = builder.Environment;
    var certPath = Path.Combine(env.ContentRootPath, "App_Data", "sso.pfx");

    options.SPOptions.NameIdPolicy = new Saml2NameIdPolicy(true, NameIdFormat.Unspecified);
    options.SPOptions.EntityId = new EntityId(baseUrl);
    options.SPOptions.PublicOrigin = new Uri(baseUrl);

    if (File.Exists(certPath))
        options.SPOptions.ServiceCertificates.Add(new X509Certificate2(certPath, "612"));

    options.IdentityProviders.Add(new IdentityProvider(
        new EntityId(ssoUrl),
        options.SPOptions)
    {
        MetadataLocation = $"{ssoUrl}idp/metadata",
        LoadMetadata = true,
        AllowUnsolicitedAuthnResponse = true
    });

    options.CookieManager = new Saml2CookieManager(baseUrlPath);
});

builder.Services.AddAuthorization();

var app = builder.Build();

var forwardedOptions = new ForwardedHeadersOptions
{
    ForwardedHeaders = ForwardedHeaders.XForwardedFor | ForwardedHeaders.XForwardedProto | ForwardedHeaders.XForwardedHost
};
forwardedOptions.KnownNetworks.Clear();
forwardedOptions.KnownProxies.Clear();
app.UseForwardedHeaders(forwardedOptions);

if (app.Environment.IsDevelopment()) {
    app.UseSwagger(c => {
        c.PreSerializeFilters.Add((swaggerDoc, httpReq) => {
            var basePath = app.Configuration["Swagger:BasePath"];
            if (!string.IsNullOrEmpty(basePath))
                swaggerDoc.Servers = [new Microsoft.OpenApi.OpenApiServer { Url = basePath }];
        });
    });
    app.UseSwaggerUI(c => {
        c.SwaggerEndpoint("v1/swagger.json", "API V1");
    });
}

app.UseHttpsRedirection();
app.UseAuthentication();
app.UseAuthorization();
app.MapSsoApi(enableTestCallback: app.Environment.IsDevelopment());
app.MapNTUCourseApi();
app.MapNTULessonsApi();
app.MapUserApi();
app.MapDepartmentsApi();
app.MapAiResultApi();
app.MapImageApi();

app.UseStaticFiles();

app.Run();

