// 學生：只看選課結果為 assigned 的課程；老師：只看自己開的課（TeacherId 對不上時退回用 TeacherName 比對）。
// 其他角色（consultant 等）目前沿用現況不過濾。
private async Task<IQueryable<Course>> ApplyUserScopeAsync(IQueryable<Course> query, ClaimsPrincipal? user)
{
    if (user is null)
        return query;

    var id = user.FindFirst("StudentId")?.Value;
    if (string.IsNullOrEmpty(id))
        return query;

    var role = user.FindFirst("UserType")?.Value;
    switch (role)
    {
        case "student":
            return query.Where(c => db.CourseSelectionResults.Any(r =>
                r.StudentId == id && r.Semester == c.Semester &&
                r.Status == "assigned" && r.CourseKey == c.CourseKey));

        case "teacher":
        {
            var byTeacherId = query.Where(c => c.TeacherId == id);
            if (await byTeacherId.AnyAsync())
                return byTeacherId;

            var name = user.FindFirst(ClaimTypes.Name)?.Value;
            if (string.IsNullOrEmpty(name))
                return byTeacherId;

            var byTeacherName = query.Where(c => c.TeacherName == name);
            if (await byTeacherName.AnyAsync())
            {
                logger.LogWarning("老師 {TeacherId} 用 TeacherId 找不到課程，改用 TeacherName={TeacherName} 比對成功。", id, name);
                return byTeacherName;
            }

            return byTeacherId;
        }

        default:
            return query;
    }
}

