"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useState,
} from "react";
import { usePathname } from "next/navigation";
import { API_BASE, redirectToLogin } from "@/lib/api";

// 對應後端 /auth/me 回傳的 UserResponse.user（SsoEndpoints.cs）
export interface AuthUser {
  id: string;
  name: string;
  department: string | null;
  departmentZh: string | null;
  departmentEn: string | null;
  role: string;
}

export type AuthStatus = "loading" | "authenticated" | "unauthenticated";

interface AuthContextValue {
  user: AuthUser | null;
  status: AuthStatus;
}

const AuthContext = createContext<AuthContextValue>({
  user: null,
  status: "loading",
});

export function useAuth(): AuthContextValue {
  return useContext(AuthContext);
}

const PUBLIC_PATHS = ["/login"]; // 其餘頁面未登入一律導回 /login

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const isPublicPath = PUBLIC_PATHS.includes(pathname);
  const [state, setState] = useState<AuthContextValue>({
    user: null,
    status: "loading",
  });

  const loadUser = useCallback(async (): Promise<AuthContextValue> => {
    const response = await fetch(`${API_BASE}/auth/me`, {
      method: "GET",
      headers: { accept: "application/json" },
    });

    if (!response.ok) return { user: null, status: "unauthenticated" };

    const resBody = await response.json();
    const raw = resBody?.user;
    if (!raw) return { user: null, status: "unauthenticated" };

    const user: AuthUser = {
      id: raw.id ?? "",
      name: raw.name ?? "",
      department: raw.department ?? null,
      departmentZh: raw.department_zh ?? raw.department ?? null,
      departmentEn: raw.department_en ?? raw.department ?? null,
      role: raw.role ?? "",
    };
    return { user, status: "authenticated" };
  }, []);

  useEffect(() => {
    let cancelled = false;

    loadUser()
      .catch(
        () => ({ user: null, status: "unauthenticated" }) as AuthContextValue,
      )
      .then((next) => {
        if (!cancelled) setState(next);
      });

    return () => {
      cancelled = true;
    };
  }, [loadUser]);

  useEffect(() => {
    if (state.status === "unauthenticated" && !isPublicPath) redirectToLogin();
  }, [state.status, isPublicPath]);

  return (
    <AuthContext.Provider value={state}>
      {isPublicPath || state.status === "authenticated" ? children : null}
    </AuthContext.Provider>
  );
}

