"use client";

import { Dropdown } from "@/components/ui/Dropdown";
import { useState, useRef, useMemo, useEffect, useLayoutEffect } from "react";
import { useRouter } from "next/navigation";
import { SearchBar, type SearchSuggestion } from "@/components/ui/SearchBar";
import Image from "@/components/AppImage";
import StatCard from "@/components/StatCard";
import Carousel from "@/components/Carousel";
import CourseItem from "@/components/CourseItem";
import {
  formatCourseSchedule,
  formatCourseScheduleTime,
} from "@/utils/course-schedule";
import { displayCourseName } from "@/utils/course-name";
import { useI18n } from "@/components/I18nProvider";
import { useShowcaseEmpty } from "@/components/ShowcaseMode";
import type { Locale } from "@/lib/i18n/locale";
import { apiFetch } from "@/lib/api";

const HEADER_TRANSITION_MS = 200;

// 學期格式化：1142 -> 114 - 2 以符合 UI 設計
const formatSemester = (semester: string) => {
  return semester.length === 4
    ? `${semester.slice(0, 3)} - ${semester.slice(3)}`
    : semester;
};

// 測試用
const TEST_LONG_NAME_COURSE = {
  courseKey: "test-long-name",
  id: "000 00000",
  name: "[TEST] 測試較長課程名稱：Lorem ipsum dolor sit amet consectetur. Dignissim elementum viverra convallis venenatis pellentesque a purus auctor. Dignissim elementum viverra convallis venenatis pellentesque a purus auctor.",
  section: "01",
  time: "一, 1-3",
  scheduleTime: "08:10 - 11:10",
  completed: 0,
  total_lessons: 0,
  course_schedule: [{ weekday: "1", start_session: "1", end_session: "3" }],
};

const TEST_STATUS_COURSE = {
  courseKey: "test-status",
  id: "000 00001",
  name: "[TEST] 測試不同分析狀態",
  section: "01",
  time: "一, 1-3",
  scheduleTime: "08:10 - 11:10",
  completed: 0,
  total_lessons: 2,
  course_schedule: [{ weekday: "1", start_session: "1", end_session: "3" }],
};

export default function CoursePage() {
  const { t, locale } = useI18n();
  const showcaseEmpty = useShowcaseEmpty();

  const [searchKeyword, setSearchKeyword] = useState("");
  const [selectedSemester, setSelectedSemester] = useState("all");
  const [courseGroups, setCourseGroups] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const formatCourseGroups = (allSemesters: any[], scheduleLocale: Locale) => {
    const groups = allSemesters.map((semester: any) => ({
      semester: semester.semester,
      courses: (semester.courses || []).map((course: any) => ({
        courseKey: course.course_key,
        id: course.course_id,
        name: course.course_name,
        nameEn: course.course_name_en,
        section: course.course_section,
        time: formatCourseSchedule(course.course_schedule, scheduleLocale),
        scheduleTime: formatCourseScheduleTime(course.course_schedule),
        completed: course.completed,
        total_lessons: course.total_lessons,
        course_schedule: course.course_schedule,
      })),
    }));

    // 按學期由新到舊排序
    groups.sort((a: any, b: any) => b.semester.localeCompare(a.semester));
    if (groups.length > 0) {
      groups[0].courses = [
        TEST_LONG_NAME_COURSE,
        TEST_STATUS_COURSE,
        ...groups[0].courses,
      ]; // 測試用
    }
    return groups;
  };

  const fetchCourses = async (semester: string, scheduleLocale: Locale) => {
    setIsLoading(true);
    try {
      const url =
        semester === "all" ? "/courses" : `/courses?semester=${semester}`;

      const response = await apiFetch(url, {
        method: "GET",
        headers: { accept: "*/*" },
      });

      if (!response.ok) throw new Error("Failed to fetch courses from API");

      const resBody = await response.json();
      const allSemesters = resBody?.semesters || [];
      setCourseGroups(formatCourseGroups(allSemesters, scheduleLocale));
      console.log("Fetched courses from API");
    } catch (error) {
      console.error(error);
      // setCourseGroups(formatCourseGroups(mockCourses.semesters, scheduleLocale));
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchCourses(selectedSemester, locale);
  }, []);

  // Reformat weekday labels when locale changes without refetching
  useEffect(() => {
    setCourseGroups((prev) =>
      prev.map((group) => ({
        ...group,
        courses: group.courses.map((course: any) => ({
          ...course,
          time: formatCourseSchedule(course.course_schedule, locale),
        })),
      })),
    );
  }, [locale]);

  const filteredCourseGroups = useMemo(() => {
    // return courseGroups
    if (showcaseEmpty) return [];

    return courseGroups
      .map((group) => {
        if (selectedSemester !== "all" && group.semester !== selectedSemester) {
          return { ...group, courses: [] };
        }

        const keyword = searchKeyword.toLowerCase();
        const filteredCourses = group.courses.filter((course: any) => {
          const zh = (course.name ?? "").toLowerCase();
          const en = (course.nameEn ?? "").toLowerCase();
          return zh.includes(keyword) || en.includes(keyword);
        });

        return {
          ...group,
          courses: filteredCourses,
        };
      })
      .filter((group: any) => group.courses.length > 0);
    // }, [searchKeyword, selectedSemester, courseGroups]);
  }, [searchKeyword, selectedSemester, courseGroups, showcaseEmpty]);

  const allCourseSuggestions = useMemo((): SearchSuggestion[] => {
    // return courseGroups.flatMap((group: any) =>
    if (showcaseEmpty) return [];

    return courseGroups.flatMap((group: any) =>
      group.courses.map((course: any) => ({
        name: displayCourseName(course.name, course.nameEn, locale),
        semester: formatSemester(group.semester),
        courseId: course.id,
        courseKey: course.courseKey,
      })),
    );
    // }, [courseGroups]);
  }, [courseGroups, showcaseEmpty, locale]);

  const getTotalLessons = () => {
    if (showcaseEmpty) return 0;
    return courseGroups
      .flatMap((group: any) =>
        group.courses.map((course: any) => course.total_lessons || 0),
      )
      .reduce((a: number, b: number) => a + b, 0);
  };

  const getTotalCompleted = () => {
    if (showcaseEmpty) return 0;
    return courseGroups
      .flatMap((group: any) =>
        group.courses.map((course: any) => course.completed || 0),
      )
      .reduce((a: number, b: number) => a + b, 0);
  };

  const getTotalCourses = () => {
    if (showcaseEmpty) return 0;
    return courseGroups.flatMap((group: any) => group.courses).length;
  };

  const hasNoCourses =
    showcaseEmpty ||
    (!isLoading &&
      courseGroups.every((group) => (group.courses?.length ?? 0) === 0));

  // empty state
  if (hasNoCourses) {
    return (
      <div className="min-h-full p-4 md:p-8 pb-[100px] md:pb-8 flex flex-col font-sans">
        <div className="flex-1 flex flex-col items-center justify-center gap-4 bg-[rgba(6,45,65,0.05)] rounded-[32px] px-8 py-16 text-center">
          <Image
            src="/images/img_status-logout.svg"
            alt=""
            width={155.56}
            height={112}
          />
          <div className="flex flex-col gap-1 items-center">
            <p className="title-2 text-gray-90">{t("course.noCoursesTitle")}</p>
            <p className="body-2-reg text-gray-70 max-w-[800px]">
              {t("course.noCoursesDescription")}{" "}
              <span className="bg-[#062D410D] px-[8px] py-[2px] rounded text-xs text-gray-90">
                #610
              </span>
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-full bg-[#F2F2F2] font-sans">
      <div className="w-full px-4 sm:px-8 pb-[100px] md:pb-8">
        <PageHeader
          searchKeyword={searchKeyword}
          onSearchKeywordChange={setSearchKeyword}
          suggestions={allCourseSuggestions}
          title={t("course.title")}
          searchPlaceholder={t("course.searchPlaceholder")}
          emptyMessage={t("course.searchNoResults")}
        />

        <Carousel>
          <StatCard
            icon="/icon/function/icon_in-progress-blue.svg"
            label={t("course.analyzing")}
            value={getTotalLessons() - getTotalCompleted()}
            hasInfo
          />
          <StatCard
            icon="/icon/function/icon_analysis-blue.svg"
            label={t("course.analyzed")}
            value={getTotalCompleted()}
          />
          <StatCard
            icon="/icon/function/icon_books-blue.svg"
            label={t("course.currentCourseCount")}
            value={getTotalCourses()}
          />
        </Carousel>

        <section className="flex flex-col gap-4">
          <div className="flex justify-end">
            <Dropdown
              label={t("course.allSemesters")}
              defaultValue="all"
              onSelect={(value) => setSelectedSemester(value)}
              items={[
                { label: t("course.allSemesters"), value: "all" },
                ...courseGroups.map((group: any) => ({
                  label: formatSemester(group.semester),
                  value: group.semester,
                })),
              ]}
            />
          </div>

          <div className="space-y-6 sm:space-y-10">
            {filteredCourseGroups.length > 0 ? (
              filteredCourseGroups.map((group) => (
                <div key={group.semester} className="space-y-3 sm:space-y-4">
                  <h2 className="title-2 text-gray-90">
                    {formatSemester(group.semester)}
                  </h2>
                  <div className="space-y-3">
                    {group.courses.map((course: any) => (
                      <CourseItem
                        key={course.courseKey}
                        {...course}
                        name={displayCourseName(
                          course.name,
                          course.nameEn,
                          locale,
                        )}
                      />
