function PageHeader({
  searchKeyword,
  onSearchKeywordChange,
  suggestions,
  title,
  searchPlaceholder,
  emptyMessage,
}: {
  searchKeyword: string;
  onSearchKeywordChange: (value: string) => void;
  suggestions: SearchSuggestion[];
  title: string;
  searchPlaceholder: string;
  emptyMessage: string;
}) {
  const router = useRouter();
  const headerRef = useRef<HTMLElement>(null);
  const headerHeightRef = useRef(0);
  const [isCollapsed, setIsCollapsed] = useState(false);

  useEffect(() => {
    const header = headerRef.current;
    if (!header) return;

    const scrollRoot =
      header.closest("main") instanceof HTMLElement
        ? (header.closest("main") as HTMLElement)
        : null;
    if (!scrollRoot) return;

    // avoid expand/collapse thrashing when header height changes
    const COLLAPSE_AT = 64;
    const EXPAND_AT = 12;

    const update = () => {
      const top = scrollRoot.scrollTop;
      setIsCollapsed((prev) => {
        if (!prev && top >= COLLAPSE_AT) return true;
        if (prev && top <= EXPAND_AT) return false;
        return prev;
      });
    };

    headerHeightRef.current = header.offsetHeight;
    update();
    scrollRoot.addEventListener("scroll", update, { passive: true });
    return () => scrollRoot.removeEventListener("scroll", update);
  }, []);

  // Keep scroll position stable while the header height animates
  useLayoutEffect(() => {
    const header = headerRef.current;
    if (!header) return;

    const scrollRoot =
      header.closest("main") instanceof HTMLElement
        ? (header.closest("main") as HTMLElement)
        : null;
    if (!scrollRoot) return;

    let rafId = 0;
    const startedAt = performance.now();

    const tick = () => {
      const nextHeight = header.offsetHeight;
      const prevHeight = headerHeightRef.current;
      const delta = prevHeight - nextHeight;

      if (prevHeight > 0 && delta !== 0) {
        scrollRoot.scrollTop += delta;
      }
      headerHeightRef.current = nextHeight;

      if (performance.now() - startedAt < HEADER_TRANSITION_MS + 50) {
        rafId = requestAnimationFrame(tick);
      }
    };

    rafId = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(rafId);
  }, [isCollapsed]);

  return (
    <header
      ref={headerRef}
      className={`sticky top-0 z-[60] -mx-4 px-4 sm:-mx-8 sm:px-8 bg-[#F2F2F2] transition-[padding,margin] duration-200 ease-out ${
        isCollapsed ? "py-4 sm:py-8 mb-4" : "pt-4 sm:pt-8 pb-4 sm:pb-6 mb-0"
      }`}
    >
      <div className="relative flex w-full flex-col md:flex-row md:items-center md:justify-end">
        <h1
          aria-hidden={isCollapsed}
          className={`text-2xl sm:title-1 font-bold text-gray-90 whitespace-nowrap overflow-hidden transition-all duration-200 ease-out md:absolute md:left-0 md:overflow-visible ${
            isCollapsed
              ? "max-h-0 opacity-0 pointer-events-none mb-0 md:max-h-none"
              : "max-h-12 opacity-100 mb-4 md:mb-0 md:max-h-none"
          }`}
        >
          {title}
        </h1>

        <div
          className={`min-w-0 w-full transition-[width] duration-200 ease-out ${
            isCollapsed ? "md:w-full" : "md:w-[320px]"
          }`}
        >
          <SearchBar
            placeholder={searchPlaceholder}
            showDropdown
            value={searchKeyword}
            onChange={onSearchKeywordChange}
            suggestions={suggestions}
            onSearch={onSearchKeywordChange}
            emptyMessage={emptyMessage}
            onSelectSuggestion={(item) => {
              if (item.courseKey) router.push(`/course/${item.courseKey}`);
            }}
          />
        </div>
      </div>
    </header>
  );
}

