129	    private static string MapRole(string accountTypeCode) => accountTypeCode switch
130	    {
131	        "u" or "g" => "student",
132	        "f" => "teacher",
133	        _ => "consultant"
134	    };
135	
136	    private static async Task SignInUserAsync(HttpContext context, string account, string name, string seq, string typeCode, string major, string authScheme)
137	    {
138	        var claims = new List<Claim>
139	        {
140	            new Claim(ClaimTypes.NameIdentifier, account),
141	            new Claim(ClaimTypes.Name, name),
142	            new Claim("StudentId", account),
143	            new Claim("AccountSeq", seq),
144	            new Claim("UserType", MapRole(typeCode)),
145	            new Claim("Major", major)
146	        };
147	
148	        var identity = new ClaimsIdentity(claims, authScheme);
149	        await context.SignInAsync(authScheme, new ClaimsPrincipal(identity));
150	    }
151	}

