CREATE TABLE "CourseSelectionResults" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "StudentId" character varying(32) NOT NULL,
    "Semester" character varying(8) NOT NULL,
    "Serial" character varying(16) NOT NULL,
