// 在開發環境模擬正式的 POST 回傳。可用 query string 指定要模擬的學號等資訊
// （例如 ?studentId=B12345678&typeCode=u），不帶就沿用預設的假資料。
if (enableTestCallback) {
    group.MapPost("/test-callback", async (HttpContext context, string? studentId, string? name, string? typeCode, string? major) => {
        var mock = ResolveMockUser(studentId, name, typeCode, major);
        await SignInUserAsync(context, mock.Account, mock.Name, mock.Account, mock.TypeCode, mock.Major, AuthScheme);

        return Results.Ok(new {
            status = "Success",
            message = "Cookie 已發放，請造訪 /auth/me 確認",
            studentId = mock.Account,
        });
    });

    // 方便直接在瀏覽器網址列輸入來模擬指定學生登入，登入後直接導去首頁，
    // 例如 /auth/test-callback?studentId=B12345678。
    group.MapGet("/test-callback", async (HttpContext context, IOptions<FutureClassroomOptions> fcOpt, string? studentId, string? name, string? typeCode, string? major) => {
        var mock = ResolveMockUser(studentId, name, typeCode, major);
        await SignInUserAsync(context, mock.Account, mock.Name, mock.Account, mock.TypeCode, mock.Major, AuthScheme);

        return Results.Redirect($"{fcOpt.Value.FrontendUrl}home");
    });
}

