// account 在 AdminAccounts 白名單裡的話，不看 AccountTypeCode，直接視為管理者/開發者，
// 不受選課/授課過濾限制（例如計中帳號本身不是課表上的授課老師，一般 typeCode="f" 會被歸類成
// teacher 但看不到任何課）。
private static string MapRole(string accountTypeCode, string account, IConfiguration configuration)
{
    var adminAccounts = configuration.GetSection("AdminAccounts").Get<string[]>() ?? [];
    if (adminAccounts.Contains(account, StringComparer.OrdinalIgnoreCase))
        return "admin";

    return accountTypeCode switch
    {
        "u" or "g" => "student",
        "f" => "teacher",
        _ => "consultant"
    };
}

