    string? studentId, string? name, string? typeCode, string? major) => (
    string.IsNullOrWhiteSpace(studentId) ? "r14725046" : studentId,
    string.IsNullOrWhiteSpace(name) ? "陳書雁" : name,
    string.IsNullOrWhiteSpace(typeCode) ? "u" : typeCode,
    string.IsNullOrWhiteSpace(major) ? "資訊管理學系" : major
);

private static async Task SignInUserAsync(HttpContext context, string account, string name, string seq, string typeCode, string major, string authScheme, IConfiguration configuration)
{
    var claims = new List<Claim>
    {
        new Claim(ClaimTypes.NameIdentifier, account),
        new Claim(ClaimTypes.Name, name),
        new Claim("StudentId", account),
        new Claim("AccountSeq", seq),
        new Claim("UserType", MapRole(typeCode, account, configuration)),
        new Claim("Major", major)
    };

    var identity = new ClaimsIdentity(claims, authScheme);
    await context.SignInAsync(authScheme, new ClaimsPrincipal(identity));
}

