using Amazon.S3;
using FutureClassroom.Core.Data;
using FutureClassroom.Core.Factory;
using FutureClassroom.Core.Jobs;
using FutureClassroom.Job.Jobs;
using FutureClassroom.Job.Jobs.Implement;
using FutureClassroom.Job.Options;
using Hangfire;
using Hangfire.PostgreSql;
using Microsoft.EntityFrameworkCore;

var builder = Host.CreateApplicationBuilder(args);

var connectionString = builder.Configuration.GetConnectionString("Default")
    ?? throw new InvalidOperationException("Connection string 'Default' not found.");

builder.Services.AddScoped<IVideoScreenshot, VideoScreenshot>();
builder.Services.AddScoped<ICourseLessonSync, CourseLessonSync>();
builder.Services.AddScoped<IDepartmentSync, DepartmentSync>();
builder.Services.AddScoped<IEnrollmentSync, EnrollmentSync>();

builder.Services.Configure<NtuCourseApiOptions>(builder.Configuration.GetSection("NtuCourseApi"));
builder.Services.AddHttpClient("NTUCourseApi").ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler
{
    SslOptions = new System.Net.Security.SslClientAuthenticationOptions
    {
        RemoteCertificateValidationCallback = (_, _, _, _) => true
    }
});

builder.Services.AddDbContextFactory<AppDbContext>(options =>
    options.UseNpgsql(connectionString));

builder.Services.AddKeyedSingleton<IAmazonS3>("minio", (_, _) =>
{
    var minioConfig = builder.Configuration.GetSection("MinIO");
    return new AmazonS3Client(minioConfig["AccessKey"] ?? "", minioConfig["SecretKey"] ?? "", new AmazonS3Config
    {
        ServiceURL = minioConfig["ServiceUrl"],
        ForcePathStyle = true,
        AuthenticationRegion = "us-east-1",
        HttpClientFactory = new BypassSslHttpClientFactory()
    });
});

builder.Services.AddKeyedSingleton<IAmazonS3>("s3", (_, _) =>
{
    var s3Config = builder.Configuration.GetSection("S3");
    return new AmazonS3Client(s3Config["AccessKey"] ?? "", s3Config["SecretKey"] ?? "", new AmazonS3Config
    {
        ServiceURL = s3Config["ServiceUrl"],
        ForcePathStyle = true,
        AuthenticationRegion = "us-east-1",
        HttpClientFactory = new BypassSslHttpClientFactory()
    });
});

builder.Services.AddHangfire(config => config
    .SetDataCompatibilityLevel(CompatibilityLevel.Version_180)
    .UseSimpleAssemblyNameTypeSerializer()
    .UseRecommendedSerializerSettings()
    .UsePostgreSqlStorage(options => options.UseNpgsqlConnection(connectionString)));

builder.Services.AddHangfireServer();

var app = builder.Build();

var recurringJobManager = app.Services.GetRequiredService<IRecurringJobManager>();
recurringJobManager.AddOrUpdate<IVideoScreenshot>(
    "video-screenshot-job",
    job => job.ExecuteAsync(),
    Cron.Hourly());

recurringJobManager.AddOrUpdate<ICourseLessonSync>(
    "course-lesson-sync-job",
    job => job.ExecuteAsync(),
    Cron.Daily(3));

recurringJobManager.AddOrUpdate<IDepartmentSync>(
    "department-sync-job",
    job => job.ExecuteAsync(),
    Cron.Daily(4));

try
{
    using var scope = app.Services.CreateScope();
    var dbFactory = scope.ServiceProvider.GetRequiredService<IDbContextFactory<AppDbContext>>();
    using var db = dbFactory.CreateDbContext();
    var bootstrapClient = app.Services.GetRequiredService<IBackgroundJobClient>();
    if (!db.Departments.Any() || !db.Departments.Any(d => d.ShortNameZh != null))
    {
        bootstrapClient.Enqueue<IDepartmentSync>(job => job.ExecuteAsync());
    }
    if (db.Courses.Any(c => string.IsNullOrEmpty(c.NameEn)))
    {
        bootstrapClient.Enqueue<ICourseLessonSync>(job => job.ExecuteAsync());
    }
}
catch (Exception ex)
{
    var logger = app.Services.GetRequiredService<ILoggerFactory>().CreateLogger("DepartmentSyncBootstrap");
    logger.LogWarning(ex, "無法檢查 Departments 是否為空，略過啟動時同步。請確認已套用 migration。");
}

#if DEBUG

var backgroundJobClient = app.Services.GetRequiredService<IBackgroundJobClient>();
backgroundJobClient.Enqueue<IVideoScreenshot>(job => job.ExecuteAsync());

#endif

app.Run();

