using FutureClassroom.Api.Services;
using FutureClassroom.Core.Helpers;

namespace FutureClassroom.Api.Endpoints
{
    public static class LessonsEndpoints
    {
        public static void MapNTULessonsApi(this WebApplication app)
        {
            var isDev = app.Environment.IsDevelopment();
            var group = app.MapGroup("/lessons");

            if (!isDev)
            {
                group.RequireAuthorization();
            }

            /// <summary>
            /// 課程互動專注百分比
            /// </summary>
            /// <returns></returns>
            group.MapGet("/latest", async (LessonService lessonService, int? limit, CancellationToken ct) =>
            {
                var result = await lessonService.GetLatestLessonsAsync(limit ?? 4, ct);
                return Results.Ok(result);
            }).WithSummary("最新分析課程列表");

            group.MapGet("/{lessonId}", async (string lessonId, LessonService lessonService) =>
            {
                lessonId = CourseHelper.DecodePathValue(lessonId);

                // lesson_id format: {semester}_{courseId}_{section}_{weekNumber}
                var parts = lessonId.Split('_');
                if (parts.Length < 4 || !int.TryParse(parts[3], out _))
                    return ApiErrors.InvalidParameter();

                var result = await lessonService.GetLessonAsync(lessonId);
                if (result is null)
                    return ApiErrors.NotFound("no_lesson_found", "No lesson found for the specified lesson ID.");

                return Results.Ok(result);
            }).WithSummary("課程互動專注百分比");
        }
    }
}

