using System.Security.Claims;
using FutureClassroom.Core.Data;
using Microsoft.EntityFrameworkCore;

namespace FutureClassroom.Api.Services;

// 集中管理「這個使用者看得到哪些課程」的規則，供 CourseService（/courses）跟
// LessonService（首頁「最新分析」「近期查看」、單堂課分析）共用，避免同一套規則兩邊各寫一次而不同步。
public class CourseAccessService(AppDbContext db, ILogger<CourseAccessService> logger)
{
    // null 代表不限制（未登入、admin、consultant 等角色）；非 null 代表只能看清單裡的 CourseKey。
    public async Task<HashSet<string>?> GetAccessibleCourseKeysAsync(ClaimsPrincipal? user)
    {
        if (user is null)
            return null;

        var id = user.FindFirst("StudentId")?.Value;
        if (string.IsNullOrEmpty(id))
            return null;

        var role = user.FindFirst("UserType")?.Value;
        switch (role)
        {
            case "student":
            {
                var keys = await db.CourseSelectionResults
                    .Where(r => r.StudentId == id && r.Status == "assigned" && r.CourseKey != null)
                    .Select(r => r.CourseKey!)
                    .Distinct()
                    .ToListAsync();
                return keys.ToHashSet();
            }

            case "teacher":
            {
                var byTeacherId = await db.Courses.Where(c => c.TeacherId == id).Select(c => c.CourseKey).ToListAsync();
                if (byTeacherId.Count > 0)
                    return byTeacherId.ToHashSet();

                var name = user.FindFirst(ClaimTypes.Name)?.Value;
                if (string.IsNullOrEmpty(name))
                    return [];

                var byTeacherName = await db.Courses.Where(c => c.TeacherName == name).Select(c => c.CourseKey).ToListAsync();
                if (byTeacherName.Count > 0)
                {
                    logger.LogWarning("老師 {TeacherId} 用 TeacherId 找不到課程，改用 TeacherName={TeacherName} 比對成功。", id, name);
                    return byTeacherName.ToHashSet();
                }

                return [];
            }

            default:
                return null;
        }
    }
}

