  courseCollectionService: CourseCollectionService;
  courseSelectionService: CourseSelectionService;
  courseTableService: CourseTableService;
  operationRecordService: OperationRecordService;
  devCourseTableService: DevCourseTableService;
  devUserService: DevUserService;
}

const OPENAPI_FILE = "openapi.yaml";

function createSwagger(server: FastifyInstance) {
  // Display swagger api docs in dev or local environment (only when file exists)
  if (env.env !== "prod" && fs.existsSync(OPENAPI_FILE)) {
    try {
      const swaggerDocument = YAML.load(OPENAPI_FILE);
      server.register(fastifySwagger, { openapi: swaggerDocument });
      server.register(fastifySwaggerUi, {
        routePrefix: "/api/v3/api-docs",
      });
    } catch (err) {
      logger.error(`Can't open ${OPENAPI_FILE}`);
    }
  }
}

export function setupRealServices(): Services {
  // Clients
  const db = new PrismaClient();
  const nolDb = new MssqlClient({
    datasources: {
      db: {
        url: env.nolDbUrl,
      },
    },
  });

  const redis = createRedisClient({
    host: env.redisUrl,
    password: env.redisPassword,
    dbIndex: env.redisDbIndex,
  });
  const elasticsearch = createElasticsearchClient({
    nodes: [env.esUrl], // TODO: Multiple urls
    auth: {
      apiKey: env.esApiKey,
    },
  });
  const nolClient = createNolClient(nolDb);

  // Repos
  const configRepo = createConfigRepo(db, redis);
  const courseRepo = createCourseRepo(db, redis);
  const courseCollectionRepo = createCourseCollectionRepo(db);
  const courseSelectionRepo = createCourseSelectionRepo(db);
  const courseTableRepo = createCourseTableRepo(db);
  const operationRecordRepo = createOperationRecordRepo(db, redis);
  const esCourseRepo = createEsCourseRepo(redis, elasticsearch, {
    courseIndex: env.esCourseIndex,
  });
  const userRepo = createUserRepo(db);
  const adminUserRepo = createAdminUserRepo(db);
  const rbacRepo = createRbacRepo(db);
  const syllabusRepo = createSyllabusRepo(db, redis); // TODO: Replace with actual syllabusRepo implementation
  const vacationCourseRepo = createVacationCourseRepo(db);
  const vacationCourseExtStuRepo = createVacationCourseExtStuRepo(db);
  const vacationCourseNtuStuRepo = createVacationCourseNtuStuRepo(db);
  const userInfoRepo = createUserInfoRepo(db);

  // Services
  const configService = createConfigService({
    configRepo,
    userRepo,
  });
  const courseService = createCourseService({
    courseRepo,
    syllabusRepo,
    esCourseRepo,
  });
  const courseCollectionService = createCourseCollectionService({
    courseRepo,
    courseCollectionRepo,
  });
  const courseTableService = createCourseTableService({
    nolClient,
    configService,
    courseRepo,
    courseTableRepo,
    userRepo,
    operationRecordRepo,
  });
  const courseSelectionService = createCourseSelectionService({
    configService,
    courseRepo,
    courseSelectionRepo,
    userRepo,
    courseTableService,
    operationRecordRepo,
  });
  const devCourseTableService = createDevCourseTableService({
    courseTableRepo,
    courseTableService,
    userRepo,
  });
  const devUserService = createDevUserService({ userRepo });
  const operationRecordService = createOperationRecordService({
    userRepo,
    operationRecordRepo,
  });
  // 申請表單系統參數載入器：redis 快取（30 分）→ 遠端 JSON → 環境變數 fallback
  const loadApplyParams = createVacationCourseParamsLoader(redis);
  const vacationCourseService = createVacationCourseService({
    vacationCourseRepo,
    userRepo,
    userInfoRepo,
    loadApplyParams,
  });
  const vacationCourseExtStuService = createVacationCourseExtStuService({
    vacationCourseExtStuRepo,
    loadApplyParams,
  });
  const vacationCourseNtuStuService = createVacationCourseNtuStuService({
    vacationCourseNtuStuRepo,
    userRepo,
    userInfoRepo,
    loadApplyParams,
  });

  const jenkinsClient = createJenkinsClient({
    baseUrl: env.jenkinsBaseUrl,
    jobName: env.jenkinsJobName,
    username: env.jenkinsUsername,
    apiToken: env.jenkinsApiToken,
    environment: env.jenkinsEnvironment,
  });
  const adminAuthService = createAdminAuthService({ adminUserRepo });
  const rbacService = createRbacService({ rbacRepo, adminUserRepo });
  const allocationService = createAllocationService({ jenkinsClient });

  const addDropService = createAddDropService({
    configService,
    courseRepo,
    courseSelectionRepo,
    courseTableService,
    courseSelectionService,
    userRepo,
    operationRecordRepo,
  });

  return {
    userRepo,
    adminUserRepo,
    rbacRepo,
    rbacService,
    addDropService,
    adminAuthService,
    allocationService,
    vacationCourseService,
    vacationCourseExtStuService,
    vacationCourseNtuStuService,
    configService,
    courseService,
    courseCollectionService,
    courseSelectionService,
    courseTableService,
    devCourseTableService,
    devUserService,
    operationRecordService,
  };
}

