/**
 * 建立 server 並註冊所有的 api routes
 */
export async function setupServer({
  addDropService,
  adminAuthService,
  allocationService,
  vacationCourseService,
  vacationCourseExtStuService,
  vacationCourseNtuStuService,
  configService,
  courseService,
  courseCollectionService,
  courseSelectionService,
  courseTableService,
  devCourseTableService,
  devUserService,
  operationRecordService,
  rbacRepo,
  rbacService,
}: Services) {
  const server = createServer({
    healthCheckPath: "/api/v3/healthz",
    apiDocs: {
      path: "/api/v3/docs",
      filePath: "openapi.yaml",
    },
  });
  server.register(createAddDropRoutes({ addDropService }));
  server.register(createAdminAuthRoutes({ adminAuthService }));
  server.register(createRbacRoutes({ rbacService, rbacRepo }));
  server.register(createAllocationAdminRoutes({ allocationService, rbacRepo }));
  server.register(createVacationCourseRoutes({ vacationCourseService }));
  server.register(
    createVacationCourseAdminRoutes({ vacationCourseService, rbacRepo }),
  );
  server.register(
    createVacationCourseExtStuRoutes({ vacationCourseExtStuService }),
  );
  server.register(
    createVacationCourseExtStuAdminRoutes({
      vacationCourseExtStuService,
      rbacRepo,
    }),
  );
  server.register(
    createVacationCourseNtuStuAdminRoutes({
      vacationCourseNtuStuService,
      rbacRepo,
    }),
  );
  server.register(
    createVacationCourseNtuStuRoutes({ vacationCourseNtuStuService }),
  );
  server.register(createConfigRoutes({ configService }));
  server.register(createConfigAdminRoutes({ configService, rbacRepo }));
  server.register(createCourseRoutes({ courseService }));
  server.register(createCourseCollectionRoutes({ courseCollectionService }));
  server.register(createCourseSelectionRoutes({ courseSelectionService }));
  server.register(createCourseTableRoutes({ courseTableService }));
  server.register(createOperationRecordRoutes({ operationRecordService }));

  // 只有在非 production 環境才會啟用 dev routes
  if (env.env !== "prod") {
    server.register(createDevAddDropRoutes({ addDropService }));
    server.register(createDevCourseTableRoutes({ devCourseTableService }));
    server.register(createDevUserRoutes({ devUserService }));
    server.register(createDevCourseSelectionRoutes({ courseSelectionService }));
    createSwagger(server);
  }

  await server.ready();
  return server;
}

export async function startServer(server: ServerInstance) {
  try {
    const port = 8080;
    const host = "0.0.0.0";
    await server.listen({ port, host });
    logger.info(`Server started on port ${port}`);

    process.on("SIGINT", async () => {
      logger.info("Received SIGINT. Closing server gracefully...");
      try {
        await server.close();
        logger.info("Server closed");
        process.exit(0);
      } catch (err) {
        logger.error("Error closing server:", err);
        process.exit(1);
      }
    });

    process.on("SIGTERM", async () => {
      logger.info("Received SIGTERM. Closing server gracefully...");
      try {
        await server.close();
        logger.info("Server closed");
        process.exit(0);
      } catch (err) {
        logger.error("Error closing server:", err);
        process.exit(1);
      }
    });
  } catch (err) {
    logger.error("Server started failed");
    logger.error(err instanceof Error ? err.stack : String(err));
    logger.error({
      errType: typeof err,
      errJson: JSON.stringify(err),
      errStr: String(err),
    });
    process.exit(1);
  }
}

/**
 * 開始執行 api server
 */
export async function exec() {
  try {
    const services = setupRealServices();
    const server = await setupServer(services);
    await startServer(server);
  } catch (err) {
    logger.error("exec() failed:");
    logger.error(err instanceof Error ? err.stack : err);
    process.exit(1);
  }
}

import { PreselectedTable, ResultTable } from "@/models/courseTable";
import { createRoute, CreateRoutes } from "@/utils/api/createRoute";

import {
  CreatePreselectedCourseRequest,
  DeletePreselectedCourseRequest,
  ExportPreselectedCoursesRequest,
  GetPreselectedTableRequest,
  GetResultTableRequest,
  SetPreselectedCoursesRequest,
} from "./schema";
import { CourseTableService } from "./service";
import { ServiceErrors } from "..";

export const createCourseTableRoutes: CreateRoutes<{
  courseTableService: CourseTableService;
}> = ({ courseTableService: service }) => {
  return async (server) => {
    createRoute({
      server,
      method: "get",
      path: "/api/v3/course-tables/preselected",
      summary: "取得使用者的預選課表",
      needAuthenticated: true,
      schemas: {
        request: GetPreselectedTableRequest,
        response: PreselectedTable,
      },
      tags: ["Course Table"],
      errors: [ServiceErrors.SemesterNotFound],
      handler: service.getPreselectedTable,
    });

    createRoute({
      server,
      method: "get",
      path: "/api/v3/course-tables/result/:semester/:phase",
      summary: "取得使用者的選課結果",
      needAuthenticated: true,
      schemas: {
        request: GetResultTableRequest,
        response: ResultTable,
      },
      tags: ["Course Table"],
      errors: [ServiceErrors.SemesterNotFound],
      handler: service.getResultTable,
    });

    createRoute({
      server,
      method: "post",
      path: "/api/v3/course-tables/preselected",
      summary: "新增預選課程至使用者的課表",
      needAuthenticated: true,
      schemas: {
        request: CreatePreselectedCourseRequest,
        response: { statusCode: 201 },
      },
      tags: ["Course Table"],
      errors: [
        ServiceErrors.CourseTableNotAvailable,
        ServiceErrors.PreselectedCourseLimitExceeded,
        ServiceErrors.CourseNotFound,
      ],
      handler: service.createPreselectedCourse,
    });

    createRoute({
      server,
      method: "put",
      path: "/api/v3/course-tables/preselected",
      summary: "修改使用者全部的預選課程",
      needAuthenticated: true,
      schemas: {
        request: SetPreselectedCoursesRequest,
        response: { statusCode: 204 },
      },
      tags: ["Course Table"],
      errors: [
        ServiceErrors.CourseTableNotAvailable,
        ServiceErrors.PreselectedCourseLimitExceeded,
        ServiceErrors.CourseNotFound,
      ],
      handler: service.setPreselectedCourses,
    });

    createRoute({
      server,
      method: "delete",
      path: "/api/v3/course-tables/preselected",
      summary: "從使用者的課程收藏中刪除課程",
      needAuthenticated: true,
      schemas: {
        request: DeletePreselectedCourseRequest,
        response: { statusCode: 204 },
      },
      tags: ["Course Table"],
      errors: [
        ServiceErrors.CourseTableNotAvailable,
        ServiceErrors.PreselectedCourseNotFound,
      ],
      handler: service.deletePreselectedCourse,
    });

    createRoute({
      server,
      method: "post",
      path: "/api/v3/course-tables/preselected/export",
      summary: "匯出使用者的預選課程至 NOL",
      needAuthenticated: true,
      schemas: {
        request: ExportPreselectedCoursesRequest,
        response: { statusCode: 204 },
      },
      tags: ["Course Table"],
      errors: [
        ServiceErrors.CourseTableNotAvailable,
        ServiceErrors.UserNotFound,
      ],
      handler: service.exportPreselectedCourses,
    });
  };
};

