386	        ...preselectedCourses.map((c) => ({
387	          serial: c.serial,
388	          semester: c.semester,
389	        })),
390	      ]);
391	
392	      const coursesMap: Record<string, Course[]> = {};
393	      for (const field of preselectedCourseFields) {
394	        coursesMap[field] = [];
395	      }
396	      for (const rawCourse of courses) {
397	        const course = formatCourse(rawCourse, Language.zh_TW);
398	        const field = getPreselectedCourseField(course);
399	        coursesMap[field].push(course);
400	      }
401	
402	      // 匯出預選課程至 nol
403	      await nolClient.exportPreselectedCourses({
404	        userSequence,
405	        coursesMap,
406	        semester,
407	      });
408	    },
409	  };
410	};
