import { Language } from "@prisma/pg/index";
import { FastifyInstance } from "fastify";
import { z, ZodSchema } from "zod";

import { AssertPermission } from "@/utils/auth/assertPermission";
import { env } from "@/utils/env";
import { CustomError, UnauthorizedError } from "@/utils/error/errors";

import { verifyAuthToken } from "./jwt";
import { registerRouteToApiDocs } from "./openapi";
import { RequestSchema, ResponseSchema } from "./schema";
import { validateRequest } from "./validation";

export type CreateRoutes<T> = (
  services: T,
) => (server: FastifyInstance) => Promise<void>;

/**
 * HTTP methods.
 */
type Method = "get" | "post" | "patch" | "delete" | "put";

interface CreateRouteProps<TParams, TQuery, TBody, TResponse> {
  /**
   * The express router to handle the route.
   */
  server: FastifyInstance;

  /**
   * The base path, for registering api docs only by concatenating with path, defaults to "".
   * @example /auth
   */
  basePath?: string;

  /**
   * The path after base path, for registering express router and api docs, e.g. /login/email.
   * @example /login/email
   */
  path: string;

  /**
   * The HTTP method.
   */
  method: Method;

  /**
   * A brief description of the route to display on api docs.
   */
  summary?: string;

  /**
   * A full description of the route to display on api docs.
   */
  description?: string;

  /**
   * A list of tags to display on api docs.
   */
  tags?: string[];

  /**
   * If the request needs to be authenticated to access by checking the auth token on the header, defaults to true.
   * Notes: if true, it will be handled by isAuthenticated middleware.
   */
  needAuthenticated: boolean;

  /**
   * Schemas to validate payload of request and response.
   * Notes: if not undefined, it will be handled by validateRequestMiddleware and validateResponseMiddleware.
   */
  schemas: {
    request: RequestSchema<TParams, TQuery, TBody>;
    response: ResponseSchema<TResponse> | ResponseSchema<TResponse>["schema"];
  };

  errors?: CustomError[];

  /**
   * 後台權限檢查（RBAC）。設定後會在驗證登入之後、呼叫 handler 之前自動執行，
   * 不需在 handler 內手動呼叫 assertPermission。
   * @example { assert: assertPermission, code: "vacation-course:manage" }
   */
  permission?: {
    assert: AssertPermission;
    code: string;
  };

  /**
   * The request handler.
   */
  handler: (
    params: TParams & TQuery & TBody & { userId: string; lang: Language },
  ) => Promise<TResponse> | TResponse;
}

/**
 * Create a route with handler, and register it to api docs by request and response schemas automatically.
 */
export function createRoute<TParams, TQuery, TBody, TResponse>({
  server,
  basePath = "",
  path,
  method,
  summary,
  description,
  tags,
  needAuthenticated,
  schemas: { request: requestSchema, response },
  errors = [],
  permission,
  handler,
}: CreateRouteProps<TParams, TQuery, TBody, TResponse>) {
  const responseSchema =
    response instanceof ZodSchema ? response : response?.schema;
  const responseStatusCode =
    response instanceof ZodSchema || response === undefined
      ? 200
      : response.statusCode;

  registerRouteToApiDocs({
    method,
    path: basePath + path,
    description,
    summary,
    tags,
    request: requestSchema,
    response: { schema: responseSchema, statusCode: responseStatusCode },
    errors,
    needAuthenticated,
  });

  server.route({
    method,
    url: path,
    handler: async (request, reply) => {
      let userId: string | undefined;
      if (needAuthenticated !== false) {
        try {
          const [, token] = request.headers.authorization?.split(" ") || [];
          const authPayload = verifyAuthToken(token, env.accessJwtSecret);
          userId = authPayload.id;
        } catch (e) {
          throw new UnauthorizedError();
        }
      }

      if (permission && userId) {
        await permission.assert(userId, permission.code);
      }

      let params = validateRequest(request, requestSchema);
      if (userId && requestSchema.auth) {
        params = { ...params, userId };
      }

      let lang: Language | undefined;
      if (requestSchema.others) {
        lang = Language.zh_TW;
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        // @ts-ignore
        const rawLang = z.nativeEnum(Language).safeParse(request.query["lang"]);
        if (rawLang.success) {
          lang = rawLang.data;
        }
      }

      console.log("Handler received params:", params);
      console.log("Request query:", request.query);

      // eslint-disable-next-line @typescript-eslint/ban-ts-comment
      // @ts-ignore
      const res = await handler({
        ...params,
        ...(lang && { lang }),
        ...(userId && { userId }),
      });
      if (responseSchema) {
        reply.status(responseStatusCode).send(res);
      } else {
        reply.status(responseStatusCode).send();
      }
    },
  });
}

/**
 * 建立「已綁定權限檢查函式」的 createRoute，讓後台模組的每個路由只需傳入
 * `permission: "vacation-course:manage"` 字串，不用每次重複帶 assertPermission。
 *
 * @example
 *   const createAdminRoute = bindAdminRoute(createAssertPermission(rbacRepo));
 *   createAdminRoute({ ..., permission: "vacation-course:manage", handler });
 */
export function bindAdminRoute(assertPermission: AssertPermission) {
  return function createAdminRoute<TParams, TQuery, TBody, TResponse>(
    props: Omit<
      CreateRouteProps<TParams, TQuery, TBody, TResponse>,
      "permission"
    > & { permission?: string },
  ) {
    const { permission: code, ...rest } = props;
    return createRoute({
      ...rest,
      permission: code ? { assert: assertPermission, code } : undefined,
    });
  };
}

