import {
  CreateDevUserRequest,
  CreateDevUserResponse,
  DeleteDevUserRequest,
  GetDevUserResponse,
  GetDevUsersRequest,
  GetTokenRequest,
  GetTokenResponse,
} from "./schema";
import { DevUserService } from "./service";
import { ServiceErrors } from "../..";

export const createDevUserRoutes: CreateRoutes<{
  devUserService: DevUserService;
}> = ({ devUserService: service }) => {
  return async (server) => {
    createRoute({
      server,
      method: "get",
      path: "/api/v3/admin/test-users",
      summary: "取得測試帳戶",
      needAuthenticated: false,
      schemas: {
        request: GetDevUsersRequest,
        response: GetDevUserResponse,
      },
      tags: ["Test Account", "Admin"],
      errors: [],
      handler: service.GetDevUser,
    });

    createRoute({
      server,
      method: "post",
      path: "/api/v3/admin/test-user",
      summary: "創建測試帳戶",
      needAuthenticated: true,
      schemas: {
        request: CreateDevUserRequest,
        response: CreateDevUserResponse,
      },
      tags: ["Test Account", "Admin"],
      errors: [ServiceErrors.UserAlreadyExists],
      handler: service.CreateDevUser,
    });

    createRoute({
      server,
      method: "delete",
      path: "/api/v3/admin/test-user",
      summary: "移除測試帳戶",
      needAuthenticated: true,
      schemas: {
        request: DeleteDevUserRequest,
        response: { statusCode: 204 },
      },
      tags: ["Test Account", "Admin"],
      errors: [ServiceErrors.UserNotFound],
      handler: service.DeleteDevUser,
    });

    createRoute({
      server,
      method: "post",
      path: "/api/v3/admin/token",
      summary: "取得 Token",
      needAuthenticated: false,
      schemas: {
        request: GetTokenRequest,
        response: GetTokenResponse,
      },
      tags: ["Test Account", "Admin"],
      errors: [],
      handler: service.GetToken,
    });
  };
};

