import {
  AssignedCourse as PrismaAssignedCourse,
  PrismaClient,
  ProgressPhase,
  SelectedCourse as PrismaSelectedCourse,
  UnassignedCourse as PrismaUnassignedCourse,
} from "@prisma/pg/index";

import { NolClient } from "@/clients/nolClient";
import { PreselectedCourse } from "@/models/courseTable";
import { handlePrismaError, PrismaError } from "@/utils/error/prisma";

import { RepoErrors } from ".";

// #################################
// Prisma
// #################################
export type RawPreselectedCourse = PreselectedCourse;
export type RawAssignedCourse = PrismaAssignedCourse;
export type RawUnassignedCourse = PrismaUnassignedCourse;
export type RawSelectedCourse = PrismaSelectedCourse;

export type RawCourseTable = {
  preselectedCourses: PreselectedCourse[];
  assignedCourses: PrismaAssignedCourse[];
  unassignedCourses: PrismaUnassignedCourse[];
  selectedCourses: PrismaSelectedCourse[];
};

/**
 * 單一選課階段的課表快照（已選上／未選上）
 */
export type RawSemesterCourseTable = {
  phase: ProgressPhase;
  assignedCourses: PrismaAssignedCourse[];
  unassignedCourses: PrismaUnassignedCourse[];
};

/**
 * 預選課程數量上限（以學期為範圍計算）
 */
export const preselectedCourseCountLimitDefault = 200;

// #################################
// Utils
// #################################
const handleError = handlePrismaError({
  [PrismaError.NotFound]: RepoErrors.NotFound,
  [PrismaError.ForeignKeyConstraint]: RepoErrors.CourseNotFound,
  [PrismaError.UniqueConstraint]: RepoErrors.Duplicated,
});

interface GetCourseTableIdOptions {
  userId: string;
  semester: string;
  phase: ProgressPhase;
}

/**
 * 取得使用者的課表 id，若不存在則建立一個新的
 */
export async function getCourseTableMetadata(
  db: PrismaClient,
  { userId, semester, phase }: GetCourseTableIdOptions,
): Promise<{ id: string }> {
  const courseTable = await db.courseTable.findUnique({
    select: {
      id: true,
    },
    where: {
      userId_semesterId_progressPhase: {
        userId,
        semesterId: semester,
        progressPhase: phase,
      },
    },
  });

  if (courseTable) {
    return { id: courseTable.id };

