import { ValidationResponseSchema } from "@/modules/courseSelection/rules/types/schemas";

export function areErrorsEqual(error1: unknown, error2: unknown): boolean {
  if (error1 instanceof Error && error2 instanceof Error) {
    return error1.message === error2.message;
  }
  return error1 === error2;
}

export function ignoreError() {}

export class CustomError extends Error {
  constructor({
    code,
    statusCode,
    message,
    cause,
  }: {
    code: string;
    statusCode: number;
    message: string;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    cause?: any;
  }) {
    super(message);
    this.code = code;
    this.statusCode = statusCode;
    this.cause = cause;
  }

  public code: string;
  public statusCode: number;
  public cause?: object;
}

export class BadRequestError extends CustomError {
  constructor(code: string, message?: string) {
    super({
      statusCode: 400,
      code: code,
      message: message ?? "Bad request",
    });
  }
}

export class ConflictError extends CustomError {
  constructor(code: string, message?: string) {
    super({
      statusCode: 409,
      code: code,
      message: message ?? "",
    });
  }
}

export class InvalidArgumentError extends BadRequestError {
  constructor() {
    super("0007", "Invalid argument");
  }
}

export class UnauthorizedError extends CustomError {
  constructor(code?: string, message?: string) {
    super({
      statusCode: 401,
      code: code ?? "0005",
      message: message ?? "Unauthorized",
    });
  }
}

export class NoPermissionError extends CustomError {
  constructor(code?: string) {
    super({
      statusCode: 403,
      code: code ?? "0006",
      message: "No permission",
    });
  }
}

export class NotFoundError extends CustomError {
  constructor(code: string, message: string) {
    super({
      statusCode: 404,
      code: code,
      message: message,
    });
  }
}

export class RouteNotFoundError extends NotFoundError {
  constructor() {
    super("0001", "Route not found");
  }
}

export class InternalServerError extends CustomError {
  constructor() {
    super({
      statusCode: 500,
      code: "0002",
      message: "Internal server error",
    });
  }
}

export class NotImplementedError extends CustomError {
  constructor() {
    super({
      statusCode: 501,
      code: "0004",
      message: "Not implemented",
    });
  }
}

export class ValidationError extends CustomError {
  constructor(
    code: string = "0006",
    message: string = "Validation fails",
    cause: ValidationResponseSchema[],
  ) {
    super({
      statusCode: 403,
      code,
      message,
      cause,
    });
  }
}

