pipeline {
    environment {
        dockerImageName = 'git.neo/jenkins/course-backend-v3-dev'
        dockerImageTag = env.BUILD_TAG.replace('%2F', '_').replace('%2f', '_')
        loginId = 'jenkins'
        gitUrl = 'https://git.neo/ntu_course_system/ntu_course_backend_v3'

        buildTimestamp = sh(script: "echo `date +%Y-%m-%d_%H:%M:%S_%Z`", returnStdout: true).trim()
        buildRandomString = sh(script: "openssl rand -hex 10", returnStdout: true).trim()

        ENV = 'dev'
        PORT = "${DEV_PORT}"
        COURSEDB_CREDS = credentials('DEV_COURSEDB_CREDS')
        BUILD_NUMBER = "${ENV}__${buildRandomString}__${buildTimestamp}"
        SITE_URL = "${DEV_SITE_URL}"
        DATABASE_URL = "${DEV_DATABASE_URL}"
        JWT_SECRET = credentials('DEV_JWT_SECRET')
        REDIS_URL = "${DEV_REDIS_URL}"
        REDIS_PASSWD = credentials('DEV_REDIS_PASSWD')
        SEPCOM_DB_CREDS = credentials('SEPCOM_DB_CREDS')
        RTCOURSE_DB_URL = "${RTCOURSE_DB_URL}"
        ELASTICSEARCH_API_KEY = credentials('DEV_ELASTICSEARCH_API_KEY')
        ELASTICSEARCH_URL = "${DEV_ELASTICSEARCH_URL}"
        ELASTICSEARCH_COURSE_INDEX_NAME = "${DEV_ELASTICSEARCH_COURSE_INDEX_NAME}"        
        JENKINS_PUSH_NOTIFICATION_TO_SLACK_TOKEN = credentials('JENKINS_PUSH_NOTIFICATION_TO_SLACK_TOKEN')
        BUILD_NOTIFICATION_SLACK_CHANNEL_ID = "${BUILD_NOTIFICATION_SLACK_CHANNEL_ID}"
        JENKINS_BASE_URL = "${JENKINS_BASE_URL}"
        JENKINS_JOB_NAME = "${JENKINS_JOB_NAME}"
        JENKINS_USERNAME = "${JENKINS_USERNAME}"
        JENKINS_API_TOKEN = credentials('JENKINS_API_TOKEN')
        JENKINS_ENVIRONMENT = "${JENKINS_ENVIRONMENT}"
        VAC_CONFIG_BASE_URL = "${DEV_VAC_CONFIG_BASE_URL}"
    }

    agent any
    options {
        ansiColor('xterm')
    }

    // parameters {
    //     gitParameter branchFilter: 'origin/(.*)', defaultValue: 'main', name: 'BRANCH', type: 'PT_BRANCH'
    // }

    stages {
        // stage('Checkout Source') {
        //     steps {
        //         git branch: "${params.BRANCH}",
        //         credentialsId: loginId,
        //         url: gitUrl
        //     }
        // }

        stage('Run Test') {
            steps {
                lock('docker-compose-for-testing') {
                    sh 'pnpm set version classic'
                    sh 'env YARN_ENABLE_IMMUTABLE_INSTALLS=false pnpm install'
                    sh 'pnpm run db:generate'
                    // catchError(buildResult: 'SUCCESS', stageResult: 'FAILURE') {
                    sh "./test.sh"
                    // }
                }
            }
        }

        stage('Build Image') {
            steps {
                script {
                    dockerImage = docker.build(
                        dockerImageName,
                        "--build-arg ENV=${ENV} --build-arg PORT=${PORT} --build-arg BUILD_NUMBER=${BUILD_NUMBER} --build-arg DATABASE_URL=${DATABASE_URL} --build-arg SITE_URL=${SITE_URL} --build-arg JWT_SECRET=${JWT_SECRET} --build-arg REDIS_URL=${REDIS_URL} --build-arg REDIS_PASSWD=${REDIS_PASSWD} --build-arg RTCOURSE_DB_URL=\"${RTCOURSE_DB_URL}\" --build-arg ELASTICSEARCH_API_KEY=${ELASTICSEARCH_API_KEY} --build-arg ELASTICSEARCH_URL=${ELASTICSEARCH_URL} --build-arg ELASTICSEARCH_COURSE_INDEX_NAME=${ELASTICSEARCH_COURSE_INDEX_NAME} --build-arg JENKINS_BASE_URL=${JENKINS_BASE_URL} --build-arg JENKINS_JOB_NAME=${JENKINS_JOB_NAME} --build-arg JENKINS_USERNAME=${JENKINS_USERNAME} --build-arg JENKINS_API_TOKEN=${JENKINS_API_TOKEN} --build-arg JENKINS_ENVIRONMENT=${JENKINS_ENVIRONMENT} --build-arg VAC_CONFIG_BASE_URL=${VAC_CONFIG_BASE_URL} ."
                    )
                }
            }
        }

        stage('Pushing Image') {
            steps {
                script {
                    docker.withRegistry('https://git.neo/jenkins', loginId) {
                        dockerImage.push("${dockerImageTag}")
                    }
                }
            }
        }

        stage('Prune Docker') {
            steps {
                sh 'if [ $(df / --output="pcent" | grep -o "[0-9]*") -gt 90 ]; then docker system prune -af; fi'
            }
        }

        stage('Build Information') {
            steps {
                sh "echo Build Environment: ${ENV}"
                // Use BuildNumber for better finding
                sh "echo BuildNumber: ${BUILD_NUMBER}"
                sh "echo Database url: ${DATABASE_URL}"
            }
        }

        stage('Deploying App to Kubernetes') {
            steps {
                // TODO: 
                // ssh clone not working. Workaround solution: https
                // Multiple ENVs support
                sh "ssh ubuntu@k8s-master.dev.neo 'git clone -b ${params.BRANCH ?: BRANCH_NAME} --single-branch https://git.neo/ntu_course_system/ntu_course_backend_v3;cd ~/ntu_course_backend_v3/helm; sed -i -e 's/{{DOCKER_TAG}}/${dockerImageTag}/g' values.yaml;sed -i -e 's/{{ENV}}/${ENV}/g' values.yaml;helm upgrade --install backend-v3-dev . -f values.yaml -f devValues.yaml;rm -rf ~/ntu_course_backend_v3';"
            }
        }

        stage('Push notification to Slack') {
            steps {
                sh """
                    curl --location --request POST 'https://slack.com/api/chat.postMessage' \
                    --header 'Authorization: Bearer ${JENKINS_PUSH_NOTIFICATION_TO_SLACK_TOKEN}' \
                    --header 'Content-Type: application/json' \
                    --data-raw '{
                    "channel": "${BUILD_NOTIFICATION_SLACK_CHANNEL_ID}",
                    "text": "`${ENV}` - Backend_v3 Deployment has been successfully deployed on `${ENV}`! ```Build Number: ${BUILD_NUMBER} \nJob: ${JOB_NAME.replace('%2F', '/').replace('%2f', '/')} \nEnvironment: ${ENV} \nTime: ${buildTimestamp}```\n **NOTICE: This might not a correct notification since we are unable to track the SSH result.**"
                    }
                    '
                """
            }
        }
    }
}

