1	using System.Net.Http.Headers;
2	using System.Net.Http.Json;
3	using System.Security.Cryptography;
4	using FutureClassroom.Core.Data;
5	using FutureClassroom.Core.Helpers;
6	using FutureClassroom.Core.Jobs;
7	using FutureClassroom.Job.Options;
8	using Microsoft.EntityFrameworkCore;
9	using Microsoft.Extensions.Options;
10	
11	namespace FutureClassroom.Job.Jobs.Implement;
12	
13	/// <summary>
14	/// 呼叫新課程網取得學生最終選課結果（Final phase）並寫入 CourseSelectionResults。
15	/// </summary>
16	public class EnrollmentSync : IEnrollmentSync
17	{
18	    private const int MaxSemesters = 3;
19	
20	    private readonly ILogger<EnrollmentSync> _logger;
21	    private readonly IDbContextFactory<AppDbContext> _dbFactory;
22	    private readonly IHttpClientFactory _httpClientFactory;
23	    private readonly IConfiguration _configuration;
24	    private readonly string _resultUrlBase;
25	
26	    public EnrollmentSync(
27	        ILogger<EnrollmentSync> logger,
28	        IDbContextFactory<AppDbContext> dbFactory,
29	        IHttpClientFactory httpClientFactory,
30	        IConfiguration configuration,
31	        IOptions<NtuCourseApiOptions> options)
32	    {
33	        _logger = logger;
34	        _dbFactory = dbFactory;
35	        _httpClientFactory = httpClientFactory;
36	        _configuration = configuration;
37	
38	        var opts = options.Value;
39	        var baseUrl = string.IsNullOrWhiteSpace(opts.SelectionResultBaseUrl) ? opts.BaseUrl : opts.SelectionResultBaseUrl;
40	        _resultUrlBase = $"{baseUrl.TrimEnd('/')}/{opts.SelectionResultPath.TrimStart('/')}";
41	    }
42	
43	    public async Task ExecuteAsync(string studentId, string semester, Guid tokenReferenceId)
44	    {
45	        _logger.LogInformation("開始同步學生 {StudentId} 學期 {Semester} 的選課結果...", studentId, semester);
46	
47	        var token = await ConsumeTokenAsync(tokenReferenceId);
48	        if (token is null)
49	        {
50	            _logger.LogWarning("找不到有效的 token 參照 {TokenReferenceId}，可能已過期或已被使用，略過同步。", tokenReferenceId);
51	            return;
52	        }
53	
54	        try
55	        {
56	            var result = await FetchResultAsync(token, semester);
57	            if (result is null)
58	            {
59	                _logger.LogWarning("學生 {StudentId} 學期 {Semester} 選課結果 API 未回傳資料。", studentId, semester);
60	                return;
61	            }
62	
63	            await UpsertAsync(studentId, semester, result);
64	            await PurgeOldSemestersAsync();
65	            _logger.LogInformation("學生 {StudentId} 學期 {Semester} 選課結果同步完成。", studentId, semester);
66	        }
67	        catch (Exception ex)
68	        {
69	            _logger.LogError(ex, "同步學生 {StudentId} 選課結果過程中發生未預期的錯誤", studentId);
70	            throw;
71	        }
72	    }
73	
74	    // Token 一次性使用：不論成功與否都會被刪除，把明文 token 在系統內的存活時間降到最低。
75	    private async Task<string?> ConsumeTokenAsync(Guid tokenReferenceId)
76	    {
77	        await using var db = await _dbFactory.CreateDbContextAsync();
78	        var pending = await db.PendingCourseNetworkTokens.FirstOrDefaultAsync(t => t.Id == tokenReferenceId);
79	        if (pending is null)
80	            return null;
81	
82	        db.PendingCourseNetworkTokens.Remove(pending);
83	        await db.SaveChangesAsync();
84	
85	        if (pending.ExpiresAt < DateTime.UtcNow)
86	            return null;
87	
88	        var key = _configuration["CourseNetworkTokenKey"];
89	        if (string.IsNullOrEmpty(key))
90	        {
91	            _logger.LogError("未設定 CourseNetworkTokenKey，無法解密 token。");
92	            return null;
93	        }
94	
95	        try
96	        {
97	            return TokenCipher.Decrypt(pending.EncryptedToken, key);
98	        }
99	        catch (CryptographicException ex)
100	        {
101	            _logger.LogError(ex, "無法解密 token 參照 {TokenReferenceId}", tokenReferenceId);
102	            return null;
103	        }
104	    }
105	
106	    private async Task<ResultTableDto?> FetchResultAsync(string token, string semester)
107	    {
108	        var semesterApi = CourseHelper.ToApiSemester(semester);
109	        var url = $"{_resultUrlBase}/{semesterApi}/Final?withCourse=true";
110	
111	        using var httpClient = _httpClientFactory.CreateClient("NTUCourseApi");
112	        using var request = new HttpRequestMessage(HttpMethod.Get, url);
113	        request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", token);
114	
115	        var response = await httpClient.SendAsync(request);
116	        if (!response.IsSuccessStatusCode)
117	        {
118	            _logger.LogWarning("選課結果 API 失敗 status={Status} url={Url}", (int)response.StatusCode, url);
119	            return null;
120	        }
121	
122	        return await response.Content.ReadFromJsonAsync<ResultTableDto>();
123	    }
124	
125	    private async Task UpsertAsync(string studentId, string semester, ResultTableDto result)
126	    {
127	        await using var db = await _dbFactory.CreateDbContextAsync();
128	
129	        var existing = await db.CourseSelectionResults
130	            .Where(r => r.StudentId == studentId && r.Semester == semester)
131	            .ToListAsync();
132	        db.CourseSelectionResults.RemoveRange(existing);
133	
134	        var serials = (result.AssignedCourses ?? [])
135	            .Concat(result.UnassignedCourses ?? [])
136	            .Select(c => c.Serial)
137	            .Where(s => !string.IsNullOrEmpty(s))
138	            .Distinct()
139	            .ToList();
140	
141	        var courseKeysBySerial = await db.Courses
142	            .Where(c => c.Semester == semester && serials.Contains(c.Serial))
143	            .ToDictionaryAsync(c => c.Serial, c => c.CourseKey);
144	
145	        var now = DateTime.UtcNow;
146	
147	        foreach (var item in result.AssignedCourses ?? [])
148	        {
149	            if (string.IsNullOrEmpty(item.Serial)) continue;
150	            db.CourseSelectionResults.Add(new CourseSelectionResult
151	            {
152	                StudentId = studentId,
153	                Semester = semester,
154	                Serial = item.Serial,
155	                CourseKey = courseKeysBySerial.GetValueOrDefault(item.Serial),
156	                Status = "assigned",
157	                Phase = item.Phase ?? "Final",
158	                Reason = null,
159	                CreatedAt = now,
160	                UpdatedAt = now
161	            });
162	        }
163	
164	        foreach (var item in result.UnassignedCourses ?? [])
165	        {
166	            if (string.IsNullOrEmpty(item.Serial)) continue;
167	            db.CourseSelectionResults.Add(new CourseSelectionResult
168	            {
169	                StudentId = studentId,
170	                Semester = semester,
171	                Serial = item.Serial,
172	                CourseKey = courseKeysBySerial.GetValueOrDefault(item.Serial),
173	                Status = "unassigned",
174	                Phase = item.Phase ?? "Final",
175	                Reason = item.Reason,
176	                CreatedAt = now,
177	                UpdatedAt = now
178	            });
179	        }
180	
181	        await db.SaveChangesAsync();
182	    }
183	
184	    // 只保留全系統最新的 3 個學期，跟哪個學生無關。
185	    private async Task PurgeOldSemestersAsync()
186	    {
187	        await using var db = await _dbFactory.CreateDbContextAsync();
188	
189	        var semesters = await db.CourseSelectionResults
190	            .Select(r => r.Semester)
191	            .Distinct()
192	            .ToListAsync();
193	
