        IDbContextFactory<AppDbContext> dbFactory,
        IHttpClientFactory httpClientFactory,
        IOptions<NtuCourseApiOptions> options)
    {
        _logger = logger;
        _dbFactory = dbFactory;
        _httpClientFactory = httpClientFactory;

        var opts = options.Value;
        var baseUrl = string.IsNullOrWhiteSpace(opts.SelectionResultBaseUrl) ? opts.BaseUrl : opts.SelectionResultBaseUrl;
        _resultUrlBase = $"{baseUrl.TrimEnd('/')}/{opts.SelectionResultPath.TrimStart('/')}";
        _apiKey = opts.FutureClassroomApiKey;
    }

    public async Task ExecuteAsync(string studentId, string semester)
    {
        _logger.LogInformation("開始同步學生 {StudentId} 學期 {Semester} 的選課結果...", studentId, semester);

        if (string.IsNullOrEmpty(_apiKey))
        {
            _logger.LogError("未設定 FutureClassroomApiKey，無法呼叫選課結果 API。");
            return;
        }

        try
        {
            var result = await FetchResultAsync(studentId, semester);
            if (result is null)
            {
                _logger.LogWarning("學生 {StudentId} 學期 {Semester} 選課結果 API 未回傳資料。", studentId, semester);
                return;
            }

            await UpsertAsync(studentId, semester, result);
            await PurgeOldSemestersAsync();
            _logger.LogInformation("學生 {StudentId} 學期 {Semester} 選課結果同步完成。", studentId, semester);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "同步學生 {StudentId} 選課結果過程中發生未預期的錯誤", studentId);
            throw;
        }
    }

    private async Task<ResultTableDto?> FetchResultAsync(string studentId, string semester)
    {
        var semesterApi = CourseHelper.ToApiSemester(semester);
        var url = $"{_resultUrlBase}/{Uri.EscapeDataString(studentId)}/{semesterApi}/Final";

        using var httpClient = _httpClientFactory.CreateClient("NTUCourseApi");
        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.Add(ApiKeyHeaderName, _apiKey);

        var response = await httpClient.SendAsync(request);
        if (!response.IsSuccessStatusCode)
        {
            _logger.LogWarning("選課結果 API 失敗 status={Status} url={Url}", (int)response.StatusCode, url);
            return null;
        }

        return await response.Content.ReadFromJsonAsync<ResultTableDto>();
    }

    private async Task UpsertAsync(string studentId, string semester, ResultTableDto result)
    {
        await using var db = await _dbFactory.CreateDbContextAsync();

        var existing = await db.CourseSelectionResults
            .Where(r => r.StudentId == studentId && r.Semester == semester)
            .ToListAsync();
        db.CourseSelectionResults.RemoveRange(existing);

        var serials = (result.AssignedCourses ?? [])
            .Concat(result.UnassignedCourses ?? [])
            .Select(c => c.Serial)
            .Where(s => !string.IsNullOrEmpty(s))
            .Distinct()
            .ToList();

        var courseKeysBySerial = await db.Courses
            .Where(c => c.Semester == semester && serials.Contains(c.Serial))
            .ToDictionaryAsync(c => c.Serial, c => c.CourseKey);

        var now = DateTime.UtcNow;

        foreach (var item in result.AssignedCourses ?? [])
        {
            if (string.IsNullOrEmpty(item.Serial)) continue;
            db.CourseSelectionResults.Add(new CourseSelectionResult
            {
                StudentId = studentId,
                Semester = semester,
                Serial = item.Serial,
                CourseKey = courseKeysBySerial.GetValueOrDefault(item.Serial),
                Status = "assigned",
                Phase = item.Phase ?? "Final",
                Reason = null,
                CreatedAt = now,
                UpdatedAt = now
            });
        }

        foreach (var item in result.UnassignedCourses ?? [])
        {
            if (string.IsNullOrEmpty(item.Serial)) continue;
            db.CourseSelectionResults.Add(new CourseSelectionResult
            {
                StudentId = studentId,
                Semester = semester,
                Serial = item.Serial,
                CourseKey = courseKeysBySerial.GetValueOrDefault(item.Serial),
                Status = "unassigned",
                Phase = item.Phase ?? "Final",
                Reason = item.Reason,
                CreatedAt = now,
                UpdatedAt = now
            });
        }

        await db.SaveChangesAsync();
    }

    // 只保留全系統最新的 3 個學期，跟哪個學生無關。
    private async Task PurgeOldSemestersAsync()
    {
        await using var db = await _dbFactory.CreateDbContextAsync();

        var semesters = await db.CourseSelectionResults
            .Select(r => r.Semester)
            .Distinct()
            .ToListAsync();

        var toKeep = semesters.OrderByDescending(s => s, StringComparer.Ordinal).Take(MaxSemesters).ToHashSet();
        var toRemove = semesters.Where(s => !toKeep.Contains(s)).ToList();
        if (toRemove.Count == 0) return;

        var deleted = await db.CourseSelectionResults
            .Where(r => toRemove.Contains(r.Semester))
            .ExecuteDeleteAsync();

        if (deleted > 0)
            _logger.LogInformation("清除舊學期選課結果，共 {Count} 筆，學期：{Semesters}", deleted, string.Join(",", toRemove));
    }

    private class ResultTableDto
    {
        public List<ResultItemDto>? AssignedCourses { get; set; }
        public List<ResultItemDto>? UnassignedCourses { get; set; }
    }

    private class ResultItemDto
    {
        public string? Serial { get; set; }
        public string? Field { get; set; }
        public string? Phase { get; set; }
        public string? Reason { get; set; }
    }
}

