1	using Microsoft.Extensions.Options;
2	using Microsoft.AspNetCore.Authentication;
3	using Microsoft.AspNetCore.Authentication.Cookies;
4	using Microsoft.EntityFrameworkCore;
5	using Sustainsys.Saml2.AspNetCore2;
6	using System.Security.Claims;
7	using FutureClassroom.Api.Models;
8	using FutureClassroom.Api.Options;
9	using FutureClassroom.Api.Services;
10	using FutureClassroom.Core.Data;
11	
12	namespace FutureClassroom.Api.Endpoints;
13	
14	public static class SsoEndpoints {
15	    private const string AuthScheme = CookieAuthenticationDefaults.AuthenticationScheme;
16	
17	    public static void MapSsoApi(this IEndpointRouteBuilder app, bool enableTestCallback = false) {
18	        var group = app.MapGroup("/auth");
19	
20	        // NTU SSO
21	        group.MapGet("/login", async (HttpContext context, IOptions<FutureClassroomOptions> fcOpt) => {
22	            try {
23	                var callbackUrl = $"{fcOpt.Value.BaseUrl}auth/callback";
24	
25	                var props = new AuthenticationProperties { RedirectUri = callbackUrl };
26	                await context.ChallengeAsync(Saml2Defaults.Scheme, props);
27	            }
28	            catch {
29	                Results.Problem("Failed to initialize login flow.", statusCode: 500);
30	            }
31	        });
32	    
33	        group.MapGet("/callback", async Task<IResult> (HttpContext context, IOptions<FutureClassroomOptions> fcOpt, IConfiguration configuration) => {
34	            var result = await context.AuthenticateAsync(AuthScheme);
35	            if (!result.Succeeded)
36	                return ApiErrors.Unauthorized("SSO authentication failed.");
37	
38	            var claimsIdentity = result.Principal?.Identity as System.Security.Claims.ClaimsIdentity;
39	            var ntuAccountName = claimsIdentity?.FindFirst("http://www.ntu.edu.tw/AccountName")?.Value;
40	            var ntuChineseName = claimsIdentity?.FindFirst("http://www.ntu.edu.tw/ChineseName")?.Value;
41	            var ntuSeq = claimsIdentity?.FindFirst("http://www.ntu.edu.tw/SEQ")?.Value;
42	            var ntuTypeCode = claimsIdentity?.FindFirst("http://www.ntu.edu.tw/AccountTypeCode")?.Value;
43	            var ntuMajor = claimsIdentity?.FindFirst("http://www.ntu.edu.tw/UNITB")?.Value;
44	
45	            await SignInUserAsync(context, ntuAccountName ?? "", ntuChineseName ?? "台大使用者", ntuSeq ?? "", ntuTypeCode ?? "", ntuMajor ?? "", AuthScheme, configuration);
46	
47	            return Results.Redirect($"{fcOpt.Value.FrontendUrl}");
48	        });
49	
50	        // 在開發環境模擬正式的 POST 回傳。可用 query string 指定要模擬的學號等資訊
51	        // （例如 ?studentId=B12345678&typeCode=u），不帶就沿用預設的假資料。
52	        if (enableTestCallback) {
53	            group.MapPost("/test-callback", async (HttpContext context, IConfiguration configuration, string? studentId, string? name, string? typeCode, string? major) => {
54	                var mock = ResolveMockUser(studentId, name, typeCode, major);
55	                await SignInUserAsync(context, mock.Account, mock.Name, mock.Account, mock.TypeCode, mock.Major, AuthScheme, configuration);
56	
57	                return Results.Ok(new {
58	                    status = "Success",
59	                    message = "Cookie 已發放，請造訪 /auth/me 確認",
60	                    studentId = mock.Account,
61	                });
62	            });
63	
64	            // 方便直接在瀏覽器網址列輸入來模擬指定學生登入，登入後直接導去首頁，
65	            // 例如 /auth/test-callback?studentId=B12345678。
66	            group.MapGet("/test-callback", async (HttpContext context, IOptions<FutureClassroomOptions> fcOpt, IConfiguration configuration, string? studentId, string? name, string? typeCode, string? major) => {
67	                var mock = ResolveMockUser(studentId, name, typeCode, major);
68	                await SignInUserAsync(context, mock.Account, mock.Name, mock.Account, mock.TypeCode, mock.Major, AuthScheme, configuration);
69	
70	                return Results.Redirect($"{fcOpt.Value.FrontendUrl}home");
71	            });
72	        }
73	
74	        group.MapGet("/logout", async Task<IResult> (
75	            HttpContext context,
76	            IWebHostEnvironment env,
77	            IOptions<NtuSsoOptions> ssoOpt,
78	            IOptions<FutureClassroomOptions> fcOpt) => {
79	
80	            await context.SignOutAsync(AuthScheme);
81	
82	            var returnUrl = $"{fcOpt.Value.FrontendUrl}login";
83	
84	            if (env.IsDevelopment())
85	                return Results.Redirect(returnUrl); // 在本機開發時導回本地端登入頁
86	
87	            var logoutUrl = $"{ssoOpt.Value.BaseUrl}logout?url={Uri.EscapeDataString(returnUrl)}";
88	
89	            return Results.Redirect(logoutUrl);
90	        });
91	        
92	        group.MapGet("/me", async (
93	            HttpContext context,
94	            DepartmentService departments,
95	            AppDbContext db,
96	            IOptions<CourseSelectionOptions> courseSelectionOptions
97	        ) => {
98	
99	            if (context.User.Identity?.IsAuthenticated != true) {
100	                return ApiErrors.Unauthorized();
101	            }
102	            var id = context.User.FindFirst("StudentId")?.Value;
103	            var name = context.User.FindFirst(ClaimTypes.Name)?.Value;
104	            var department = context.User.FindFirst("Major")?.Value;
105	            var role = context.User.FindFirst("UserType")?.Value;
106	
107	            var resolved = await departments.FindByMajorAsync(department);
108	
109	            // 只有學生需要走新課程網選課結果同步；沒有該學期資料代表要導去前端 OAuth 流程。
110	            var needsCourseSync = false;
111	            if (role == "student" && !string.IsNullOrEmpty(id)) {
112	                var currentSemester = courseSelectionOptions.Value.CurrentSemester;
113	                needsCourseSync = !await db.CourseSelectionResults
114	                    .AnyAsync(r => r.StudentId == id && r.Semester == currentSemester);
115	            }
116	
117	            return Results.Ok(new UserResponse(
118	                User: new UserInfo(
119	                    Id: id ?? "",
120	                    Name: name ?? "",
121	                    Department: department,
122	                    DepartmentZh: resolved?.NameZh ?? department,
123	                    DepartmentEn: resolved?.NameEn ?? department,
124	                    Role: role ?? "",
125	                    NeedsCourseSync: needsCourseSync
126	                )
127	            ));
128	        });
129	 
130	    }
131	
132	    // account 在 AdminAccounts 白名單裡的話，不看 AccountTypeCode，直接視為管理者/開發者，
133	    // 不受選課/授課過濾限制（例如計中帳號本身不是課表上的授課老師，一般 typeCode="f" 會被歸類成
134	    // teacher 但看不到任何課）。
135	    private static string MapRole(string accountTypeCode, string account, IConfiguration configuration)
136	    {
137	        var adminAccounts = configuration.GetSection("AdminAccounts").Get<string[]>() ?? [];
138	        if (adminAccounts.Contains(account, StringComparer.OrdinalIgnoreCase))
139	            return "admin";
140	
141	        return accountTypeCode switch
142	        {
143	            "u" or "g" => "student",
144	            "f" => "teacher",
145	            _ => "consultant"
146	        };
147	    }
148	
149	    // 開發用的假帳號，未帶 query string 時沿用原本寫死的預設值（陳書雁 / 學生）。
150	    private static (string Account, string Name, string TypeCode, string Major) ResolveMockUser(
151	        string? studentId, string? name, string? typeCode, string? major) => (
152	        string.IsNullOrWhiteSpace(studentId) ? "r14725046" : studentId,
153	        string.IsNullOrWhiteSpace(name) ? "陳書雁" : name,
154	        string.IsNullOrWhiteSpace(typeCode) ? "u" : typeCode,
155	        string.IsNullOrWhiteSpace(major) ? "資訊管理學系" : major
156	    );
157	
158	    private static async Task SignInUserAsync(HttpContext context, string account, string name, string seq, string typeCode, string major, string authScheme, IConfiguration configuration)
159	    {
160	        var claims = new List<Claim>
161	        {
162	            new Claim(ClaimTypes.NameIdentifier, account),
163	            new Claim(ClaimTypes.Name, name),
164	            new Claim("StudentId", account),
165	            new Claim("AccountSeq", seq),
166	            new Claim("UserType", MapRole(typeCode, account, configuration)),
167	            new Claim("Major", major)
168	        };
169	
170	        var identity = new ClaimsIdentity(claims, authScheme);
171	        await context.SignInAsync(authScheme, new ClaimsPrincipal(identity));
172	    }
173	}

