private static async Task SignInUserAsync(
    HttpContext context, string account, string name, string seq, string typeCode, string major, string authScheme,
    IConfiguration configuration, AppDbContext db, IBackgroundJobClient backgroundJobClient, IOptions<CourseSelectionOptions> courseSelectionOptions)
{
    var role = MapRole(typeCode, account, configuration);
    var claims = new List<Claim>
    {
        new Claim(ClaimTypes.NameIdentifier, account),
        new Claim(ClaimTypes.Name, name),
        new Claim("StudentId", account),
        new Claim("AccountSeq", seq),
        new Claim("UserType", role),
        new Claim("Major", major)
    };

    var identity = new ClaimsIdentity(claims, authScheme);
    await context.SignInAsync(authScheme, new ClaimsPrincipal(identity));

    await TriggerEnrollmentSyncIfNeededAsync(account, role, db, backgroundJobClient, courseSelectionOptions);
}

// 學生第一次登入（或選課結果被 3 學期保留策略清掉後）時，後端直接觸發 job 撈選課紀錄，
// 不需要學生做任何額外動作（不用走前端 OAuth，改由新課程網提供的 server-to-server API 查詢）。
private static async Task TriggerEnrollmentSyncIfNeededAsync(
    string studentId, string role, AppDbContext db, IBackgroundJobClient backgroundJobClient, IOptions<CourseSelectionOptions> courseSelectionOptions)
{
    if (role != "student") return;

    var currentSemester = courseSelectionOptions.Value.CurrentSemester;
    if (string.IsNullOrEmpty(currentSemester)) return;

    var alreadySynced = await db.CourseSelectionResults
        .AnyAsync(r => r.StudentId == studentId && r.Semester == currentSemester);
    if (alreadySynced) return;

    backgroundJobClient.Enqueue<IEnrollmentSync>(job => job.ExecuteAsync(studentId, currentSemester));
}

