import { Language, ProgressPhase } from "@prisma/pg/index";

import { NolClient } from "@/clients/nolClient";
import { Course, formatCourse } from "@/models/course/course";
import {
  formatPreselectedTable,
  formatResultTable,
  getPreselectedCourseField,
  preselectedCourseFields,
  PreselectedTable,
  ResultTable,
} from "@/models/courseTable";
import { OperationType } from "@/models/operationRecord";
import { ConfigService } from "@/modules/config/service";
import { RepoErrors } from "@/repos";
import { CourseRepo } from "@/repos/courseRepo";
import { CourseTableRepo } from "@/repos/courseTableRepo";
import { OperationRecordRepo } from "@/repos/operationRecordRepo";
import { UserRepo } from "@/repos/userRepo";
import { areErrorsEqual } from "@/utils/error/errors";

import {
  CreatePreselectedCourseRequest,
  DeletePreselectedCourseRequest,
  ExportPreselectedCoursesRequest,
  GetPreselectedTableRequest,
  GetResultTableRequest,
  SetPreselectedCoursesRequest,
} from "./schema";
import { ServiceErrors } from "..";
import { ListProgressesRequest } from "../config/schema";

// #################################
// Utils
// #################################
function handleError(err: unknown): never {
  if (areErrorsEqual(err, RepoErrors.NotFound)) {
    throw ServiceErrors.PreselectedCourseNotFound;
  }
  if (areErrorsEqual(err, RepoErrors.LimitExceeded)) {
    throw ServiceErrors.PreselectedCourseLimitExceeded;
  }
  if (areErrorsEqual(err, RepoErrors.SemesterNotFound)) {
    throw ServiceErrors.SemesterNotFound;
  }
  if (areErrorsEqual(err, RepoErrors.CourseNotFound)) {
    throw ServiceErrors.CourseNotFound;
  }
  if (areErrorsEqual(err, RepoErrors.Duplicated)) {
    throw ServiceErrors.AlreadyPreselected;
  }
  throw err;
}

const progressPhases: ProgressPhase[] = [
  ProgressPhase.PreReg1,
  ProgressPhase.PreReg2,
  ProgressPhase.AddDrop1,
  ProgressPhase.AddDrop2,
  ProgressPhase.AddDrop3,
  ProgressPhase.AddDrop4,
  ProgressPhase.AddDrop5,
  ProgressPhase.AddDrop6,
  ProgressPhase.Final,
];

/**
 * 取得一個選課進度的上一個選課進度
 */
function getLastProgressPhase(
  progressPhase: ProgressPhase,
): ProgressPhase | null {
  const index = progressPhases.indexOf(progressPhase);
  if (index <= 0) {
    return null;
  }
  return progressPhases[index - 1];
}

// #################################
// Service
// #################################
export const createCourseTableService = ({
  nolClient,
  configService,
  courseRepo,
  courseTableRepo,
  userRepo,
  operationRecordRepo,
}: {
  nolClient: NolClient;
  configService: ConfigService;
  courseRepo: CourseRepo;
  courseTableRepo: CourseTableRepo;
  userRepo: UserRepo;
  operationRecordRepo: OperationRecordRepo;
}) => {
  async function getLastPhaseAssignedCourse(
    req: GetPreselectedTableRequest,
    options: ListProgressesRequest = {},
  ) {
    const { semester, progress } = await configService.listProgresses(options);
    if (!progress) {
      throw ServiceErrors.CourseTableNotAvailable;
    }
    const lastPhase = getLastProgressPhase(progress.phase);

    if (lastPhase) {
      // 取得上個選課階段的已選上課程
      const courseTable = await courseTableRepo
        .getCourseTable({
          nolClient,
          userId: req.userId,
          semester: semester,
          phase: lastPhase,
          withAssigned: true,
        })
        .catch(handleError);
      return courseTable.assignedCourses;
    }
    return [];
  }

  return {
    /**
     * 取得上個階段的已選上課程
     */
    getLastPhaseAssignedCourse: async (
      req: GetPreselectedTableRequest,
      options: ListProgressesRequest = {},
    ) => {
      const rawAssignedCourses = await getLastPhaseAssignedCourse(req, options);
      const rawCourses = await courseRepo.getMany([
        ...rawAssignedCourses.map(({ courseId }) => courseId),
      ]);
      const courses = rawCourses.map((course) =>
        formatCourse(course, req.lang),
      );

      return rawAssignedCourses.map(({ courseId }) => ({
        courseId,
        course: courses.find(({ id }) => id === courseId),
      }));
    },
    /**
     * 取得使用者的預選課表
     * 預選課表 = 預選課程 + 上個階段的已選上課程
     */
    getPreselectedTable: async (
      req: GetPreselectedTableRequest,
      options: ListProgressesRequest = {},
    ): Promise<PreselectedTable> => {
      const { semester, progress } =
        await configService.listProgresses(options);
      if (!progress) {
        throw ServiceErrors.CourseTableNotAvailable;
      }
      const phase = progress.phase;
      const assignedCourses = await getLastPhaseAssignedCourse(req, options);
      const { sequence: userSequence } = await userRepo
        .get(req.userId)
        .catch((err) => {
          if (areErrorsEqual(err, RepoErrors.NotFound)) {
            throw ServiceErrors.UserNotFound;
          }
          throw err;
        });
      const { preselectedCourses } = await courseTableRepo.getCourseTable({
        nolClient,
        userId: req.userId,
        semester: semester,
        phase: phase,
        withPreselected: true,
        userSequence,
      });
      let courses: Course[] = [];
      if (req.withCourse) {
        const rawCourses = [
          ...(await courseRepo.getCoursesWithSerial([
            ...preselectedCourses.map((c) => ({
              serial: c.serial,
              semester: c.semester,
            })),
          ])),
          ...(await courseRepo.getMany([
            ...assignedCourses.map(({ courseId }) => courseId),
          ])),
        ];

        courses = rawCourses.map((course) => formatCourse(course, req.lang));
      }

      return formatPreselectedTable({
        rawPreselectedCourses: preselectedCourses,
        rawAssignedCourses: assignedCourses,
        courses,
      });
    },

    /**
     * 取得使用者的選課結果
     * 選課結果 = 已選上課程 + 未選上課程
     */
    getResultTable: async (
      req: GetResultTableRequest,
    ): Promise<ResultTable> => {
      const { assignedCourses, unassignedCourses } = await courseTableRepo
        .getCourseTable({
          userId: req.userId,
          semester: req.semester,
          phase: req.phase,
          withAssigned: true,
          withUnassigned: true,
        })
        .catch(handleError);

      let courses: Course[] = [];
      if (req.withCourse) {
        const rawCourses = await courseRepo.getMany([
          ...assignedCourses.map(({ courseId }) => courseId),
          ...unassignedCourses.map(({ courseId }) => courseId),
        ]);
        courses = rawCourses.map((course) => formatCourse(course, req.lang));
      }

      return formatResultTable({
        rawAssignedCourses: assignedCourses,
        rawUnassignedCourses: unassignedCourses,
        courses,
      });
    },

    /**
     * 新增預選課程至使用者的課表
     */
    createPreselectedCourse: async (
      req: CreatePreselectedCourseRequest,
    ): Promise<void> => {
      // 取得當前的選課進度
      const { semester, progress } = await configService.listProgresses({});
      if (!progress) {
        throw ServiceErrors.CourseTableNotAvailable;
      }

      const { sequence: userSequence } = await userRepo
        .get(req.userId)
        .catch((err) => {
          if (areErrorsEqual(err, RepoErrors.NotFound)) {
            throw ServiceErrors.UserNotFound;
          }
          throw err;
        });

      // TODO: 目前將課程網志願序的功能移除，未來若要重新加上再做調整
      await nolClient.insertPreselectedCourse({
        userSequence,
        semester: semester,
        serial: req.serial,
        wishNo: 1,
      });

      // 操作記錄 - 新增課程
      const course = (
        await courseRepo.getCoursesWithSerial([
          {
            serial: req.serial,
            semester: semester,
          },
        ])
      )[0]?.id;

      if (!course) throw ServiceErrors.CourseNotFound;

      operationRecordRepo.recordUserOperation({
        semesterId: semester,
        studentId: req.userId,
        operation: OperationType.AddCourse,
        courseId: course,
      });
    },

    /**
     * 修改使用者全部的預選課程
     */
    setPreselectedCourses: async (
      req: SetPreselectedCoursesRequest,
    ): Promise<void> => {
      // 取得當前的選課進度
      const { semester, progress } = await configService.listProgresses({});
      if (!progress) {
        throw ServiceErrors.CourseTableNotAvailable;
      }

      await courseTableRepo
        .setPreselectedCourses({
          userId: req.userId,
          courseIds: req.courseIds,
          phase: progress.phase,
          semester,
        })
        .catch(handleError);

      operationRecordRepo.recordUserOperation({
        semesterId: semester,
        studentId: req.userId,
        operation: OperationType.MoveOrder,
      });
    },

    /**
     * 刪除使用者的預選課程
     */
    deletePreselectedCourse: async (
      req: DeletePreselectedCourseRequest,
    ): Promise<void> => {
      // 取得當前的選課進度
      const { semester, progress } = await configService.listProgresses({});
      if (!progress) {
        throw ServiceErrors.CourseTableNotAvailable;
      }
      const { sequence: userSequence } = await userRepo
        .get(req.userId)
        .catch((err) => {
          if (areErrorsEqual(err, RepoErrors.NotFound)) {
            throw ServiceErrors.UserNotFound;
          }
          throw err;
        });

      // 操作記錄 - 刪除課程
      const course = (
        await courseRepo.getCoursesWithSerial([
          {
            serial: req.serial,
            semester: semester,
          },
        ])
      )[0]?.id;

      if (!course) throw ServiceErrors.CourseNotFound;

      await nolClient.deletePreselectedCourse({
        userSequence,
        semester: semester,
        serial: req.serial,
      });

      operationRecordRepo.recordUserOperation({
        semesterId: semester,
        studentId: req.userId,
        operation: OperationType.RemoveCourse,
        courseId: course,
      });
    },

    /**
     * 匯出使用者的預選課程至 NOL
     */
    exportPreselectedCourses: async (
      req: ExportPreselectedCoursesRequest,
    ): Promise<void> => {
      // 取得當前的選課進度
      const { semester, progress } = await configService.listProgresses({});
      if (!progress) {
        throw ServiceErrors.CourseTableNotAvailable;
      }

      // 取得使用者的學號
      const { sequence: userSequence } = await userRepo
        .get(req.userId)
        .catch((err) => {
          if (areErrorsEqual(err, RepoErrors.NotFound)) {
            throw ServiceErrors.UserNotFound;
          }
          throw err;
        });

      // 取得使用者的預選課程
      const { preselectedCourses } = await courseTableRepo
        .getCourseTable({
          userId: req.userId,
          semester: semester,
          phase: progress.phase,
          withPreselected: true,
        })
        .catch(handleError);

      // 將預選課程依照課程類型分類
      const courses = await courseRepo.getCoursesWithSerial([
        ...preselectedCourses.map((c) => ({
          serial: c.serial,
          semester: c.semester,
        })),
      ]);

      const coursesMap: Record<string, Course[]> = {};
      for (const field of preselectedCourseFields) {
        coursesMap[field] = [];
      }
      for (const rawCourse of courses) {
        const course = formatCourse(rawCourse, Language.zh_TW);
        const field = getPreselectedCourseField(course);
        coursesMap[field].push(course);
      }

      // 匯出預選課程至 nol
      await nolClient.exportPreselectedCourses({
        userSequence,
        coursesMap,
        semester,
      });
    },
  };
};

export type CourseTableService = ReturnType<typeof createCourseTableService>;

import dotenv from "dotenv";

dotenv.config();

type Env = "local" | "dev" | "prod" | "test";

export const env = {
  env: (process.env.ENV as Env) || "local",
  isDebugMode: process.env.IS_DEBUG_MODE !== "0" || false,
  buildNumber: process.env.BUILD_NUMBER || "",
  port: process.env.PORT || 8080,
  accessJwtSecret: process.env.ACCESS_JWT_SECRET || "nksnfoiehhrekwqnrlkje",
  redisUrl: process.env.REDIS_URL || "localhost",
  redisPassword: process.env.REDIS_PASSWD || "",
  redisDbIndex: Number(process.env.REDIS_DB_INDEX || "0"),
  nolDbUrl: process.env.RTCOURSE_DB_URL as string,
  siteUrl: process.env.SITE_URL || "http://localhost:8080",
  esUrl: process.env.ELASTICSEARCH_URL as string,
  esUsername: process.env.ELASTICSEARCH_USERNAME as string,
  esPassword: process.env.ELASTICSEARCH_PASSWORD as string,
  esApiKey: process.env.ELASTICSEARCH_API_KEY as string,
  esCourseIndex: process.env.ELASTICSEARCH_COURSE_INDEX_NAME as string,
};

