  // Services
  const configService = createConfigService({
    configRepo,
    userRepo,
  });
  const courseService = createCourseService({
    courseRepo,
    syllabusRepo,
    esCourseRepo,
  });
  const courseCollectionService = createCourseCollectionService({
    courseRepo,
    courseCollectionRepo,
  });
  const courseTableService = createCourseTableService({
    nolClient,
    configService,
    courseRepo,
    courseTableRepo,
    userRepo,
    operationRecordRepo,
  });
  const courseSelectionService = createCourseSelectionService({
    configService,
    courseRepo,
    courseSelectionRepo,
    userRepo,
    courseTableService,
  });
  const devCourseTableService = createDevCourseTableService({
    courseTableRepo,
    courseTableService,
    userRepo,
  });
  const devUserService = createDevUserService({ userRepo });
  const operationRecordService = createOperationRecordService({
    userRepo,
    operationRecordRepo,
  });

  return {
    configService,
    courseService,
    courseCollectionService,
    courseSelectionService,
    courseTableService,
    devCourseTableService,
    devUserService,
    operationRecordService,
  };
}

/**
 * 建立假的 services 以避免真的連接到資料庫與其他服務
 */
export function setupMockServices(): Services {
  const configService = createConfigService({
    configRepo: mock(),
    userRepo: mock(),
  });
  const courseService = createCourseService({
    courseRepo: mock(),
    syllabusRepo: mock(),
    esCourseRepo: mock(),
  });
  const courseCollectionService = createCourseCollectionService({
    courseRepo: mock(),
    courseCollectionRepo: mock(),
  });
  const courseTableService = createCourseTableService({
    nolClient: mock(),
    configService,
    courseRepo: mock(),
    courseTableRepo: mock(),
    userRepo: mock(),
    operationRecordRepo: mock(),
  });
  const courseSelectionService = createCourseSelectionService({
    configService,
    courseRepo: mock(),
    courseSelectionRepo: mock(),
    userRepo: mock(),
    courseTableService,
  });
  const devCourseTableService = createDevCourseTableService({
    courseTableRepo: mock(),
    courseTableService: mock(),
    userRepo: mock(),
  });
  const devUserService = createDevUserService({
    userRepo: mock(),
  });
  const operationRecordService = createOperationRecordService({
    userRepo: mock(),
    operationRecordRepo: mock(),
  });
  return {
    configService,
    courseService,
    courseCollectionService,
    courseSelectionService,
    courseTableService,
    devCourseTableService,
    devUserService,
    operationRecordService,
  };
}

/**
 * 建立 server 並註冊所有的 api routes
 */
export async function setupServer({
  configService,
  courseService,
  courseCollectionService,
  courseSelectionService,
  courseTableService,
  devCourseTableService,
  devUserService,
  operationRecordService,
}: Services) {
  const server = createServer({
    healthCheckPath: "/api/v3/healthz",
    apiDocs: {
      path: "/api/v3/docs",
      filePath: "openapi.yaml",
    },
  });
  server.register(createConfigRoutes({ configService }));
  server.register(createCourseRoutes({ courseService }));
  server.register(createCourseCollectionRoutes({ courseCollectionService }));
  server.register(createCourseSelectionRoutes({ courseSelectionService }));
  server.register(createCourseTableRoutes({ courseTableService }));
  server.register(createOperationRecordRoutes({ operationRecordService }));

  // 只有在非 production 環境才會啟用 dev routes
  if (env.env !== "prod") {
    server.register(createDevCourseTableRoutes({ devCourseTableService }));
    server.register(createDevUserRoutes({ devUserService }));
    server.register(createDevCourseSelectionRoutes({ courseSelectionService }));
    createSwagger(server);
  }

  await server.ready();
  return server;
}

export async function startServer(server: ServerInstance) {
  try {
    const port = 8080;
    const host = "0.0.0.0";
    await server.listen({ port, host });
    logger.info(`Server started on port ${port}`);

    process.on("SIGINT", async () => {
      logger.info("Received SIGINT. Closing server gracefully...");
      try {
        await server.close();
        logger.info("Server closed");
        process.exit(0);
      } catch (err) {
        logger.error("Error closing server:", err);
        process.exit(1);
      }
    });

    process.on("SIGTERM", async () => {
      logger.info("Received SIGTERM. Closing server gracefully...");
      try {
        await server.close();
        logger.info("Server closed");
        process.exit(0);
      } catch (err) {
        logger.error("Error closing server:", err);
        process.exit(1);
      }
    });
  } catch (err) {
    logger.error("Server started failed");
    logger.error(err);
    process.exit(1);
  }
}

/**
 * 開始執行 api server
 */
export async function exec() {
  const services = setupRealServices();
  const server = await setupServer(services);
  startServer(server);
}

