import { ProgressPhase } from "@prisma/pg/index";
import { FastifyInstance } from "fastify";
import { z } from "zod";

import { env } from "@/utils/env";
import { BadRequestError, UnauthorizedError } from "@/utils/error/errors";

import { FutureclassroomService } from "./service";

const ParamsSchema = z.object({
  sequence: z.string().min(1),
  semester: z.string().min(1),
  phase: z.nativeEnum(ProgressPhase),
});

/**
 * 給 FutureClassroom 這個獨立校內系統用的選課結果查詢 API。
 *
 * 刻意不透過 createRoute()（共用的 JWT 驗證流程），而是獨立註冊路由、
 * 自己做 API Key 驗證，避免任何一絲一毫影響到既有路由的驗證邏輯與行為。
 * 只有一支新端點，找不到就是完全沒接、找得到也不影響其他任何路由。
 */
export const createFutureclassroomRoutes =
  ({
    futureclassroomService: service,
  }: {
    futureclassroomService: FutureclassroomService;
  }) =>
  async (server: FastifyInstance) => {
    server.get(
      "/api/v3/futureclassroom/course-tables/result/:sequence/:semester/:phase",
      async (request, reply) => {
        const apiKey = request.headers["x-futureclassroom-key"];
        if (!env.futureclassroomApiKey || apiKey !== env.futureclassroomApiKey) {
          throw new UnauthorizedError();
        }

        const parsed = ParamsSchema.safeParse(request.params);
        if (!parsed.success) {
          throw new BadRequestError("9002", "Invalid params");
        }

        const { sequence, semester, phase } = parsed.data;
        const result = await service.getResultTableBySequence({
          sequence,
          semester,
          phase,
        });
        reply.status(200).send(result);
      },
    );
  };

