import { Language, ProgressPhase } from "@prisma/pg/index";

import { UserRepo } from "@/repos/userRepo";
import { NotFoundError } from "@/utils/error/errors";

import { CourseTableService } from "../courseTable/service";

// 這個 shape 刻意跟 courseTable 模組內部的 ResultTable schema 脫鉤：main／production
// 兩個分支的 AssignedCourse/UnassignedCourse 內部欄位不完全一樣（例如 production 分支
// 是用 courseId + 巢狀 course 物件表示，不像這裡直接有 serial 欄位），這裡統一轉成
// FutureClassroom 期待的穩定格式（serial 在最外層），這樣不管未來各分支內部的
// ResultTable 實作怎麼變，呼叫端的合約都不會被影響到。
export interface FutureclassroomResultItem {
  serial: string;
  reason?: string | null;
}

export interface FutureclassroomResultTable {
  assignedCourses: FutureclassroomResultItem[];
  unassignedCourses: FutureclassroomResultItem[];
}

/**
 * 給 FutureClassroom（校內另一個獨立系統）用的選課結果查詢服務。
 *
 * 跟一般使用者走的 `GET /course-tables/result/:semester/:phase` 差在：這裡不需要學生本人
 * 登入取得的 JWT，改用學號（sequence）直接查，由呼叫端（FutureClassroom 後端）用 API Key
 * 驗證身分（見 routes.ts），適合背景 job 這種沒有瀏覽器 session 的場景。
 */
export const createFutureclassroomService = ({
  userRepo,
  courseTableService,
}: {
  userRepo: UserRepo;
  courseTableService: CourseTableService;
}) => {
  return {
    getResultTableBySequence: async ({
      sequence,
      semester,
      phase,
    }: {
      sequence: string;
      semester: string;
      phase: ProgressPhase;
    }): Promise<FutureclassroomResultTable> => {
      const user = await userRepo.getBySequence(sequence);
      if (!user) {
        throw new NotFoundError(
          "9001",
          `User not found for sequence: ${sequence}`,
        );
      }

      const result = await courseTableService.getResultTable({
        userId: user.id,
        semester,
        phase,
        lang: Language.zh_TW,
        withCourse: true,
      });

      return {
        assignedCourses: result.assignedCourses.map((c) => ({
          serial: c.serial,
        })),
        unassignedCourses: result.unassignedCourses.map((c) => ({
          serial: c.serial,
          reason: c.reason,
        })),
      };
    },
  };
};

export type FutureclassroomService = ReturnType<
  typeof createFutureclassroomService
>;

