import { PrismaClient, User as PrismaUser } from "@prisma/pg/index";

import { handlePrismaError, PrismaError } from "@/utils/error/prisma";

import { RepoErrors } from ".";

// #################################
// Prisma
// #################################
export type RawUser = PrismaUser;

// #################################
// Utils
// #################################
const handleError = handlePrismaError({
  [PrismaError.NotFound]: RepoErrors.NotFound,
  [PrismaError.UniqueConstraint]: RepoErrors.UserAlreadyExists,
});

// #################################
// Repo
// #################################
export function createUserRepo(db: PrismaClient) {
  return {
    /**
     * 取得使用者
     */
    get: async (id: string): Promise<RawUser> => {
      // TODO: Add cache
      return await db.user
        .findUniqueOrThrow({ where: { id } })
        .catch(handleError);
    },
    getAllTestUser: async (): Promise<RawUser[]> => {
      return await db.user
        .findMany({
          where: {
            userType: "TestStudent",
          },
        })
        .catch(handleError);
    },
    create: async (userContent: PrismaUser): Promise<RawUser> => {
      return await db.user
        .create({
          data: userContent,
        })
        .catch(handleError);
    },
    deleteDevUser: async (sequence: string): Promise<RawUser> => {
      return await db.user
        .delete({
          where: {
            sequence: sequence,
            userType: "TestStudent",
          },
        })
        .catch(handleError);
    },
    /**
     * 用學號查使用者，查無資料回傳 null（給 FutureClassroom 的 server-to-server 查詢用）
     */
    getBySequence: async (sequence: string): Promise<RawUser | null> => {
      return await db.user.findUnique({ where: { sequence } });
    },
  };
}

export type UserRepo = ReturnType<typeof createUserRepo>;

