input.new_string:
/**
 * 用學號查使用者，查無資料回傳 null（給 FutureClassroom 的 server-to-server 查詢用）。
 * 不分大小寫比對：資料庫實際存的 sequence 是小寫，但呼叫端可能傳大寫學號進來
 * （例如 FutureClassroom 那邊從台大 SSO 拿到的學號格式就是大寫），
 * 用 findUnique 精確比對會查不到人，所以改用 findFirst + insensitive mode。
 */
getBySequence: async (sequence: string): Promise<RawUser | null> => {
  return await db.user.findFirst({
    where: { sequence: { equals: sequence, mode: "insensitive" } },
  });
},

